struct DirectBinaryParent {
    left: NodeRef,
    left_is_binary: bool,
    operator: SyntaxKind,
}

impl PrimitiveBinaryPlan {
    pub(super) const fn node(&self) -> NodeRef {
        self.node
    }

    pub(super) const fn operator(&self) -> SyntaxKind {
        self.operator
    }

    pub(super) const fn operands(&self) -> (&PlannedExpression, &PlannedExpression) {
        (&self.left, &self.right)
    }

    pub(super) fn shorthand_assignment_initializer(&self) -> Option<&PlannedExpression> {
        self.shorthand_assignment
            .as_ref()
            .map(|assignment| &assignment.initializer)
    }
}

impl LogicalBinaryPlan {
    pub(super) const fn node(&self) -> NodeRef {
        self.node
    }

    pub(super) const fn operator(&self) -> SyntaxKind {
        self.operator
    }

    pub(super) const fn operands(&self) -> (&PlannedExpression, &PlannedExpression) {
        (&self.left, &self.right)
    }
}

