    #[test]
    fn unsupported_function_loops_fail_before_source_publication() {
        for (index, body) in [
            "while (flag) consume(flag);",
            "while (flag) { return; }",
            "for (const index = 0; index < 1; ++index) {}",
            "for (let [index] = [0]; index < 1; ++index) {}",
        ]
        .into_iter()
        .enumerate()
        {
            let text =
                format!("const ready = 1; function repeat(flag: boolean): void {{ {body} }}",);
            let source = parsed(&text);
            let file = FileId::new(8_487 + u32::try_from(index).unwrap());
            let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());
            let ready = variable_symbol(&context, &source, file, "ready");
            let cold = observable_state(&context, file);

            assert!(
                matches!(
                    context.check_source_file(file),
                    Err(SourceCheckError::Unsupported(
                        UnsupportedSourceSyntax::Function(SourceFunctionUnsupported::FunctionBody(
                            _
                        ))
                    )),
                ),
                "unexpectedly admitted unsupported function loop: {body}",
            );
            assert_eq!(observable_state(&context, file), cold);
            assert!(context.store().value_symbol_links(ready).is_none());
            assert!(context.diagnostics().is_empty());
        }
    }

    #[test]
    fn for_in_lexical_keys_remain_strings_in_calls_and_captured_arrows() {
        let source = parsed(concat!(
            "declare function use(value: string): void; ",
            "declare function capture(value: any): void; ",
            "const key = 1; ",
            "for (let key in { first: 1 }) { ",
            "use(key); capture(() => key); (() => key); ",
            "} ",
            "for (const key in { second: 2 }) { use(key); } ",
            "for (const unused in {}) {} ",
            "capture(key);",
        ));
        let file = FileId::new(8_480);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        assert!(context.diagnostics().is_empty());
        let (_, bound) = context.file(file).unwrap();
        let mut loops = source
            .arena
            .iter()
            .filter_map(|(node, record)| {
                let NodeData::ForInOrOfStatement(iteration) = &record.data else {
                    return None;
                };
                if record.kind != SyntaxKind::ForInStatement {
                    return None;
                }
                let NodeData::VariableDeclarationList(bindings) =
                    &source.arena.get(iteration.initializer)?.data
                else {
                    return None;
                };
                let declaration = NodeRef::new(
                    source.arena.id(),
                    file,
                    *bindings.declarations.nodes.first()?,
                );
                Some((
                    NodeRef::new(source.arena.id(), file, node),
                    bound.symbol(declaration)?,
                ))
            })
            .collect::<Vec<_>>();
        loops.sort_unstable_by_key(|(node, _)| source.arena.get(node.node).unwrap().range.start);
        let [(_, first), (_, second), (_, unused)] = loops.as_slice() else {
            panic!("expected three authenticated for-in bindings")
        };
        let string = context.store().intrinsic_bootstrap().unwrap().string_type;
        for symbol in [*first, *second, *unused] {
            assert_eq!(
                context
                    .store()
                    .value_symbol_links(symbol)
                    .and_then(|links| links.resolved_type),
                Some(string),
            );
        }
        assert_ne!(first, second);

        let top_level = variable_symbol(&context, &source, file, "key");
        let top_level_type = variable_value_type(&context, &source, file, "key");
        let mut reads = identifier_expressions(&source, file, "key");
        reads.sort_unstable_by_key(|node| source.arena.get(node.node).unwrap().range.start);
        let [
            first_call,
            call_capture,
            direct_capture,
            second_call,
            trailing,
        ] = reads.as_slice()
        else {
            panic!("expected the loop reads, captured arrows, and trailing top-level read")
        };
        for (node, expected) in [
            (*first_call, *first),
            (*call_capture, *first),
            (*direct_capture, *first),
            (*second_call, *second),
        ] {
            assert_eq!(
                context
                    .store()
                    .symbol_node_links(node)
                    .and_then(|links| links.resolved_symbol),
                Some(expected),
            );
            assert_eq!(resolved_node_type(&context, node), string);
        }
        assert_eq!(
            context
                .store()
                .symbol_node_links(*trailing)
                .and_then(|links| links.resolved_symbol),
            Some(top_level),
        );
        assert_eq!(resolved_node_type(&context, *trailing), top_level_type);

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn for_in_anonymous_closures_return_captured_arrows_with_stable_callable_identity() {
        let source = parsed(concat!(
            "declare function use(value: any): void; ",
            "const key = 1; ",
            "for (let key in { first: 1 }) { ",
            "((function () { return (() => key); })); ",
            "} ",
            "for (const key in { second: 2 }) { ",
            "(function () { return () => key; }); ",
            "} ",
            "use(key);",
        ));
        let file = FileId::new(9_360);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let (_, bound) = context.file(file).unwrap();
        let mut loops = source
            .arena
            .iter()
            .filter_map(|(node, record)| {
                let NodeData::ForInOrOfStatement(iteration) = &record.data else {
                    return None;
                };
                if record.kind != SyntaxKind::ForInStatement {
                    return None;
                }
                let NodeData::VariableDeclarationList(bindings) =
                    &source.arena.get(iteration.initializer)?.data
                else {
                    return None;
                };
                let [binding] = bindings.declarations.nodes.as_slice() else {
                    return None;
                };
                Some((
                    NodeRef::new(source.arena.id(), file, node),
                    bound.symbol(NodeRef::new(source.arena.id(), file, *binding))?,
                ))
            })
            .collect::<Vec<_>>();
        loops.sort_unstable_by_key(|(node, _)| source.arena.get(node.node).unwrap().range.start);
        let [(_, first_key), (_, second_key)] = loops.as_slice() else {
            panic!("expected one let binding and one const binding")
        };

        let string = context.store().intrinsic_bootstrap().unwrap().string_type;
        let outer_key = variable_symbol(&context, &source, file, "key");
        for symbol in [*first_key, *second_key] {
            assert_ne!(symbol, outer_key);
            assert_eq!(
                context
                    .store()
                    .value_symbol_links(symbol)
                    .and_then(|links| links.resolved_type),
                Some(string),
            );
        }
        assert_ne!(first_key, second_key);

        let mut functions = source
            .arena
            .iter()
            .filter_map(|(node, record)| {
                (record.kind == SyntaxKind::FunctionExpression).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .collect::<Vec<_>>();
        functions.sort_unstable_by_key(|node| source.arena.get(node.node).unwrap().range.start);
        let mut arrows = source
            .arena
            .iter()
            .filter_map(|(node, record)| {
                (record.kind == SyntaxKind::ArrowFunction).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .collect::<Vec<_>>();
        arrows.sort_unstable_by_key(|node| source.arena.get(node.node).unwrap().range.start);
        assert_eq!(functions.len(), 2);
        assert_eq!(arrows.len(), 2);

        let mut callable_identities = Vec::new();
        for (function, arrow) in functions.iter().copied().zip(arrows.iter().copied()) {
            let function_owner = bound.symbol(function).unwrap();
            let arrow_owner = bound.symbol(arrow).unwrap();
            let function_type = context
                .store()
                .source_callable_type_for_owner(function_owner)
                .unwrap();
            let arrow_type = context
                .store()
                .source_callable_type_for_owner(arrow_owner)
                .unwrap();
            assert_eq!(resolved_node_type(&context, function), function_type);
            assert_eq!(resolved_node_type(&context, arrow), arrow_type);
            assert_eq!(
                context.type_to_string(function_type).unwrap(),
                "() => () => string"
            );
            assert_eq!(context.type_to_string(arrow_type).unwrap(), "() => string");

            let function_signature = context
                .store()
                .source_callable_provenance(function_type)
                .unwrap()
                .signature;
            let arrow_signature = context
                .store()
                .source_callable_provenance(arrow_type)
                .unwrap()
                .signature;
            assert_eq!(
                context
                    .store()
                    .signature(function_signature)
                    .unwrap()
                    .resolved_return_type(),
                Some(arrow_type),
            );
            assert_eq!(
                context
                    .store()
                    .signature(arrow_signature)
                    .unwrap()
                    .resolved_return_type(),
                Some(string),
            );
            callable_identities.push((function_owner, function_type, arrow_owner, arrow_type));
        }

        let mut reads = identifier_expressions(&source, file, "key");
        reads.sort_unstable_by_key(|node| source.arena.get(node.node).unwrap().range.start);
        let [first_capture, second_capture, trailing] = reads.as_slice() else {
            panic!("expected two captured loop keys and one top-level key")
        };
        for (read, expected) in [
            (*first_capture, *first_key),
            (*second_capture, *second_key),
            (*trailing, outer_key),
        ] {
            assert_eq!(
                context
                    .store()
                    .symbol_node_links(read)
                    .and_then(|links| links.resolved_symbol),
                Some(expected),
            );
        }
        assert_eq!(resolved_node_type(&context, *first_capture), string);
        assert_eq!(resolved_node_type(&context, *second_capture), string);
        assert_eq!(
            resolved_node_type(&context, *trailing),
            variable_value_type(&context, &source, file, "key"),
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
        for (function_owner, function_type, arrow_owner, arrow_type) in callable_identities {
            assert_eq!(
                context
                    .store()
                    .source_callable_type_for_owner(function_owner),
                Some(function_type),
            );
            assert_eq!(
                context.store().source_callable_type_for_owner(arrow_owner),
                Some(arrow_type),
            );
        }
    }

    #[test]
    fn for_in_captured_closures_reject_named_or_parameterized_function_expressions() {
        for (index, expression) in [
            "(function named() { return () => key; });",
            "(function (value) { return () => key; });",
        ]
        .into_iter()
        .enumerate()
        {
            let text = format!("const key = 1; for (let key in {{ first: 1 }}) {{ {expression} }}");
            let source = parsed(&text);
            let file = FileId::new(9_361 + u32::try_from(index).unwrap());
            let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());
            let function = source
                .arena
                .iter()
                .find_map(|(node, record)| {
                    (record.kind == SyntaxKind::FunctionExpression).then_some(NodeRef::new(
                        source.arena.id(),
                        file,
                        node,
                    ))
                })
                .unwrap();
            let (_, bound) = context.file(file).unwrap();
            let owner = bound.symbol(function).unwrap();
            let outer_key = variable_symbol(&context, &source, file, "key");
            let cold = observable_state(&context, file);

            assert!(matches!(
                context.check_source_file(file),
                Err(SourceCheckError::Unsupported(UnsupportedSourceSyntax::Syntax {
                    node,
                    kind: SyntaxKind::FunctionExpression,
                    role: SourceSyntaxRole::VariableInitializer,
                })) if node == function
            ));
            assert_eq!(observable_state(&context, file), cold);
            assert!(
                context
                    .store()
                    .source_callable_type_for_owner(owner)
                    .is_none()
            );
            assert!(context.store().value_symbol_links(outer_key).is_none());
            assert!(context.diagnostics().is_empty());
        }
    }

    #[test]
    fn labeled_for_in_closures_preserve_lexical_capture_and_callable_identity() {
        let source = parsed(concat!(
            "declare function use(value: any): void; ",
            "const key = 1; ",
            "outer: for (let key in { first: 1 }) { ",
            "(function () { return key; }); (() => key); ",
            "} ",
            "first: second: for (const key in { second: 2 }) { ",
            "(function () { return (() => key); }); (() => key); ",
            "} ",
            "use(key);",
        ));
        let file = FileId::new(9_363);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let (_, bound) = context.file(file).unwrap();
        let mut loops = source
            .arena
            .iter()
            .filter_map(|(node, record)| {
                let NodeData::ForInOrOfStatement(iteration) = &record.data else {
                    return None;
                };
                if record.kind != SyntaxKind::ForInStatement {
                    return None;
                }
                let NodeData::VariableDeclarationList(bindings) =
                    &source.arena.get(iteration.initializer)?.data
                else {
                    return None;
                };
                let [binding] = bindings.declarations.nodes.as_slice() else {
                    return None;
                };
                Some((
                    NodeRef::new(source.arena.id(), file, node),
                    bound.symbol(NodeRef::new(source.arena.id(), file, *binding))?,
                ))
            })
            .collect::<Vec<_>>();
        loops.sort_unstable_by_key(|(node, _)| source.arena.get(node.node).unwrap().range.start);
        let [(_, first_key), (_, second_key)] = loops.as_slice() else {
            panic!("expected one single-label loop and one double-label loop")
        };

        let string = context.store().intrinsic_bootstrap().unwrap().string_type;
        let outer_key = variable_symbol(&context, &source, file, "key");
        for symbol in [*first_key, *second_key] {
            assert_ne!(symbol, outer_key);
            assert_eq!(
                context
                    .store()
                    .value_symbol_links(symbol)
                    .and_then(|links| links.resolved_type),
                Some(string),
            );
        }
        assert_ne!(first_key, second_key);

        let mut functions = source
            .arena
            .iter()
            .filter_map(|(node, record)| {
                (record.kind == SyntaxKind::FunctionExpression).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .collect::<Vec<_>>();
        functions.sort_unstable_by_key(|node| source.arena.get(node.node).unwrap().range.start);
        let [direct_function, nested_function] = functions.as_slice() else {
            panic!("expected one anonymous function in each labeled loop")
        };

        let mut callable_identities = Vec::new();
        for (function, expected) in [
            (*direct_function, "() => string"),
            (*nested_function, "() => () => string"),
        ] {
            let owner = bound.symbol(function).unwrap();
            let callable = context
                .store()
                .source_callable_type_for_owner(owner)
                .unwrap();
            assert_eq!(resolved_node_type(&context, function), callable);
            assert_eq!(context.type_to_string(callable).unwrap(), expected);
            callable_identities.push((owner, callable));
        }

        let mut arrows = source
            .arena
            .iter()
            .filter_map(|(node, record)| {
                (record.kind == SyntaxKind::ArrowFunction).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .collect::<Vec<_>>();
        arrows.sort_unstable_by_key(|node| source.arena.get(node.node).unwrap().range.start);
        assert_eq!(arrows.len(), 3);
        for arrow in arrows {
            let owner = bound.symbol(arrow).unwrap();
            let callable = context
                .store()
                .source_callable_type_for_owner(owner)
                .unwrap();
            assert_eq!(resolved_node_type(&context, arrow), callable);
            assert_eq!(context.type_to_string(callable).unwrap(), "() => string");
            callable_identities.push((owner, callable));
        }

        let mut reads = identifier_expressions(&source, file, "key");
        reads.sort_unstable_by_key(|node| source.arena.get(node.node).unwrap().range.start);
        let [
            first_function,
            first_arrow,
            nested_arrow,
            second_arrow,
            trailing,
        ] = reads.as_slice()
        else {
            panic!("expected four loop captures and one top-level key")
        };
        for (read, expected) in [
            (*first_function, *first_key),
            (*first_arrow, *first_key),
            (*nested_arrow, *second_key),
            (*second_arrow, *second_key),
            (*trailing, outer_key),
        ] {
            assert_eq!(
                context
                    .store()
                    .symbol_node_links(read)
                    .and_then(|links| links.resolved_symbol),
                Some(expected),
            );
        }
        assert_eq!(
            resolved_node_type(&context, *trailing),
            variable_value_type(&context, &source, file, "key"),
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
        for (owner, callable) in callable_identities {
            assert_eq!(
                context.store().source_callable_type_for_owner(owner),
                Some(callable)
            );
        }
    }

