    #[test]
    fn missing_const_enum_members_report_initializer_and_property_diagnostics_in_order() {
        let source = parsed(concat!(
            "const enum E1 { ",
            "Existing = 1, ",
            "Y = E1.Z, ",
            "Y1 = E1['Z'], ",
            "Wrapped = ((E1.WrappedMissing)), ",
            "Receiver = (E1).ReceiverMissing, ",
            "Template = ((E1)[`TemplateMissing`]), ",
            "Valid = E1.Existing, ",
            "Unknown = missing, ",
            "}",
        ));
        let file = FileId::new(9_394);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let diagnostics = context.diagnostics().as_slice();
        assert_eq!(
            diagnostics
                .iter()
                .map(|diagnostic| diagnostic.diagnostic.code())
                .collect::<Vec<_>>(),
            [
                2474, 2339, 2474, 2339, 2474, 2339, 2474, 2339, 2474, 2339, 2474
            ],
        );
        assert_eq!(
            diagnostics
                .iter()
                .map(|diagnostic| node_text(&source, diagnostic.node.unwrap()))
                .collect::<Vec<_>>(),
            [
                "E1.Z",
                "Z",
                "E1['Z']",
                "'Z'",
                "((E1.WrappedMissing))",
                "WrappedMissing",
                "(E1).ReceiverMissing",
                "ReceiverMissing",
                "((E1)[`TemplateMissing`])",
                "`TemplateMissing`",
                "missing",
            ],
        );
        for (diagnostic, member) in [
            (&diagnostics[1], "Z"),
            (&diagnostics[3], "Z"),
            (&diagnostics[5], "WrappedMissing"),
            (&diagnostics[7], "ReceiverMissing"),
            (&diagnostics[9], "TemplateMissing"),
        ] {
            assert_eq!(diagnostic.diagnostic.arguments, [member, "typeof E1"]);
            assert_eq!(
                diagnostic.diagnostic.render().unwrap(),
                format!("Property '{member}' does not exist on type 'typeof E1'."),
            );
            let node = diagnostic.node.unwrap();
            assert!(context.store().type_node_links(node).is_none());
            assert!(context.store().symbol_node_links(node).is_none());
        }
        let owner = global_symbol(&context, "E1");
        assert!(context.store().declared_type_links(owner).is_some());
        assert!(context.store().value_symbol_links(owner).is_some());
        let warm = observable_state(&context, file);

        context.recheck_source_file(file).unwrap();

        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn prior_enum_and_class_names_are_exact_property_receivers() {
        let source = parsed(concat!(
            "enum Status { Ready } ",
            "class Model { static count: number; } ",
            "const selected = Status.Ready; ",
            "Model;",
        ));
        let file = FileId::new(8_294);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let enum_owner = global_symbol(&context, "Status");
        let enum_member = context
            .store()
            .symbol(enum_owner)
            .and_then(ts_binder::semantic::Symbol::exports)
            .and_then(|exports| context.store().symbol_table(exports))
            .and_then(|exports| exports.get_source("Ready"))
            .expect("Status.Ready must be a published enum member");
        let enum_type = context
            .store()
            .value_symbol_links(enum_member)
            .and_then(|links| links.resolved_type)
            .expect("Status.Ready must retain its enum literal type");
        assert_eq!(
            variable_value_type(&context, &source, file, "selected"),
            enum_type
        );
        let class_owner = global_symbol(&context, "Model");
        let class_read = source
            .arena
            .iter()
            .find_map(|(node, record)| {
                let NodeData::Identifier(identifier) = &record.data else {
                    return None;
                };
                (identifier.text == "Model"
                    && record
                        .parent
                        .and_then(|parent| source.arena.get(parent))
                        .is_some_and(|parent| parent.kind == SyntaxKind::ExpressionStatement))
                .then_some(NodeRef::new(source.arena.id(), file, node))
            })
            .expect("the source contains one standalone Model value read");
        assert_eq!(
            resolved_node_type(&context, class_read),
            context
                .store()
                .value_symbol_links(class_owner)
                .and_then(|links| links.resolved_type)
                .expect("the class constructor value must be published")
        );
        assert!(context.diagnostics().is_empty());
        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn unsupported_later_enum_prevents_earlier_enum_publication() {
        let source = parsed("enum Good { A } enum Bad { A = runtime }");
        let file = FileId::new(411);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());
        let good = global_symbol(&context, "Good");
        let bad = source
            .arena
            .iter()
            .filter(|(_, record)| record.kind == SyntaxKind::EnumDeclaration)
            .map(|(node, _)| NodeRef::new(source.arena.id(), file, node))
            .nth(1)
            .expect("second enum declaration must exist");
        let before = observable_state(&context, file);

        assert_eq!(
            context.check_source_file(file),
            Err(SourceCheckError::Unsupported(
                UnsupportedSourceSyntax::Enum(bad)
            ))
        );
        assert_eq!(observable_state(&context, file), before);
        assert!(context.store().declared_type_links(good).is_none());
        assert!(context.store().value_symbol_links(good).is_none());
        assert!(context.diagnostics().is_empty());
        assert!(!is_type_checked(&context, file));
    }

