    #[test]
    fn class_order_recovery_rejects_forged_owners_and_poisoned_reference_caches() {
        for (index, deferred) in [false, true].into_iter().enumerate() {
            let source = parsed(if deferred {
                DEFERRED_CLASS_ORDER_SOURCE
            } else {
                FORWARD_CLASS_ORDER_SOURCE
            });
            let file = FileId::new(11_742 + u32::try_from(index).unwrap());
            let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());
            let owner = global_symbol(&context, if deferred { "bar" } else { "B" });
            let other = global_symbol(&context, if deferred { "baz" } else { "A" });
            let member = context
                .store()
                .symbol(owner)
                .and_then(ts_binder::semantic::Symbol::members)
                .and_then(|members| context.store().symbol_table(members))
                .and_then(|members| members.get_source(if deferred { "baz" } else { "bar" }))
                .unwrap();
            assert!(context.store_mut_for_test().set_symbol_relationships(
                member,
                None,
                None,
                Some(other),
                None,
            ));
            let poisoned = observable_state(&context, file);

            assert!(
                context.check_source_file(file).is_err(),
                "deferred={deferred}"
            );
            assert_eq!(observable_state(&context, file), poisoned);
            assert!(context.diagnostics().is_empty());
        }

        let source = parsed(FORWARD_CLASS_ORDER_SOURCE);
        let file = FileId::new(11_744);
        let mut forward_context = context(&[(file, &source)], CanonicalCheckerOptions::default());
        let reference = source
            .arena
            .iter()
            .find_map(|(_, record)| {
                let NodeData::ExpressionWithTypeArguments(heritage) = &record.data else {
                    return None;
                };
                Some(NodeRef::new(source.arena.id(), file, heritage.expression))
            })
            .unwrap();
        let wrong = forward_context
            .store()
            .intrinsic_bootstrap()
            .unwrap()
            .number_type;
        assert!(forward_context.store_mut_for_test().set_type_node_links(
            reference,
            TypeNodeLinks {
                resolved_type: Some(wrong),
                ..TypeNodeLinks::default()
            },
        ));
        let poisoned = observable_state(&forward_context, file);

        assert!(forward_context.check_source_file(file).is_err());
        assert_eq!(observable_state(&forward_context, file), poisoned);
        assert!(forward_context.diagnostics().is_empty());

        for (index, exports) in [false, true].into_iter().enumerate() {
            let source = parsed(DEFERRED_CLASS_ORDER_SOURCE);
            let file = FileId::new(11_745 + u32::try_from(index).unwrap());
            let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());
            let owner = global_symbol(&context, "bar");
            let members = context
                .store()
                .symbol(owner)
                .and_then(ts_binder::semantic::Symbol::members)
                .unwrap();
            let constructor = context
                .store()
                .symbol_table(members)
                .and_then(|members| {
                    members.get(ts_binder::InternalSymbolName::Constructor.as_ref())
                })
                .unwrap();
            assert!(context.store_mut_for_test().set_symbol_relationships(
                constructor,
                (!exports).then_some(members),
                exports.then_some(members),
                Some(owner),
                None,
            ));
            let poisoned = observable_state(&context, file);

            assert!(
                context.check_source_file(file).is_err(),
                "constructor exports={exports}"
            );
            assert_eq!(observable_state(&context, file), poisoned);
            assert!(context.diagnostics().is_empty());
        }
    }

    #[test]
    fn protected_constructors_remain_accessible_inside_generic_descendant_methods() {
        let source = parsed(concat!(
            "class C { protected constructor() {} }\n",
            "class B<T = any> extends C {}\n",
            "class A extends B { f() { new A(); } }",
        ));
        let file = FileId::new(9_930);
        let mut context = context(
            &[(file, &source)],
            CanonicalCheckerOptions {
                no_implicit_any: true,
                ..CanonicalCheckerOptions::default()
            },
        );
        let base = global_symbol(&context, "C");
        let middle = global_symbol(&context, "B");
        let derived = global_symbol(&context, "A");
        let constructor = source
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::Constructor).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .unwrap();
        let default = source
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::AnyKeyword).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .unwrap();
        let (construction, reference) = source
            .arena
            .iter()
            .find_map(|(node, record)| {
                let NodeData::NewExpression(expression) = &record.data else {
                    return None;
                };
                Some((
                    NodeRef::new(source.arena.id(), file, node),
                    NodeRef::new(source.arena.id(), file, expression.expression),
                ))
            })
            .unwrap();

        context.check_source_file(file).unwrap();

        assert!(context.diagnostics().is_empty());
        assert!(is_type_checked(&context, file));
        assert!(
            context
                .store()
                .declared_type_links(middle)
                .and_then(|links| links.declared_type)
                .is_some()
        );
        let instance = context
            .store()
            .declared_type_links(derived)
            .and_then(|links| links.declared_type)
            .unwrap();
        assert_eq!(resolved_node_type(&context, construction), instance);
        assert_eq!(
            resolved_node_type(&context, default),
            context.store().intrinsic_bootstrap().unwrap().any_type,
        );
        assert_eq!(
            context
                .store()
                .symbol_node_links(reference)
                .and_then(|links| links.resolved_symbol),
            Some(derived),
        );
        let signature = context
            .store()
            .signature_links(construction)
            .and_then(|links| links.resolved_signature.signature())
            .and_then(|signature| context.store().signature(signature))
            .unwrap();
        assert_eq!(signature.declaration(), Some(constructor));
        assert_eq!(signature.resolved_return_type(), Some(instance));
        let inherited = context.get_nongeneric_class_members(base).unwrap();
        assert_eq!(
            context
                .store()
                .signature(inherited.default_construct_signature())
                .and_then(super::super::signatures::Signature::declaration),
            Some(constructor),
        );

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

