    #[test]
    fn computed_enum_const_assertions_preserve_member_identity_and_mutable_widening() {
        let source = parsed(concat!(
            "declare function computed(value: number): number; ",
            "enum E { A = computed(0), B = computed(1) } ",
            "const preserved = E.B as const; ",
            "const wrapped = (E.B) as const; ",
            "let indexed = E['B'] as const; ",
            "let widened = E.B; ",
            "let asserted = E.B as const; ",
            "const exact = E.A; ",
            "enum Literal { First = 1, Second = 2 } ",
            "let literal = Literal.First as const;",
        ));
        let file = FileId::new(9_390);
        let mut context = context(
            &[(file, &source)],
            CanonicalCheckerOptions {
                intrinsic: IntrinsicBootstrapOptions {
                    strict_null_checks: true,
                    ..IntrinsicBootstrapOptions::default()
                },
                no_implicit_any: true,
                ..CanonicalCheckerOptions::default()
            },
        );

        context.check_source_file(file).unwrap();

        let owner = global_symbol(&context, "E");
        let declared = context
            .store()
            .declared_type_links(owner)
            .and_then(|links| links.declared_type)
            .expect("the computed enum must retain its declared union");
        let exports = context
            .store()
            .symbol(owner)
            .and_then(ts_binder::semantic::Symbol::exports)
            .and_then(|exports| context.store().symbol_table(exports))
            .unwrap();
        let first = exports.get_source("A").unwrap();
        let second = exports.get_source("B").unwrap();
        let first_fresh = context
            .store()
            .value_symbol_links(first)
            .and_then(|links| links.resolved_type)
            .unwrap();
        let second_fresh = context
            .store()
            .value_symbol_links(second)
            .and_then(|links| links.resolved_type)
            .unwrap();
        let TypeData::Literal(second_literal) =
            context.store().type_payload(second_fresh).unwrap().data()
        else {
            panic!("computed enum members must retain their exact literal identity")
        };
        let second_regular = second_literal.regular_type;

        assert_ne!(first_fresh, second_fresh);
        assert_eq!(
            context.store().type_payload(first_fresh).unwrap().flags(),
            TypeFlags::ENUM,
        );
        assert_eq!(
            variable_value_type(&context, &source, file, "exact"),
            first_fresh,
        );
        assert_eq!(
            variable_value_type(&context, &source, file, "widened"),
            declared,
        );
        for name in ["preserved", "wrapped", "indexed", "asserted"] {
            let assertion = variable_initializer(&source, file, name);
            assert_eq!(
                variable_value_type(&context, &source, file, name),
                second_regular,
            );
            assert_eq!(resolved_node_type(&context, assertion), second_regular);
            assert_eq!(
                context.store().assertion_links(assertion),
                Some(&AssertionLinks {
                    expr_type: Some(second_fresh),
                }),
            );
            assert_eq!(context.type_to_string(second_regular).unwrap(), "E.B");
        }
        assert_eq!(
            context
                .type_to_string(variable_value_type(&context, &source, file, "literal"))
                .unwrap(),
            "Literal.First",
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn computed_local_enum_returns_preserve_union_identity_and_diagnostic_order() {
        let source = parsed(concat!(
            "declare function computed(value: number): number; ",
            "function selected() { ",
            "return Dynamic.Second; ",
            "enum Dynamic { First = computed(0), Second = computed(1) } ",
            "}",
        ));
        let file = FileId::new(9_391);
        let mut context = context(
            &[(file, &source)],
            CanonicalCheckerOptions {
                allow_unreachable_code: Some(false),
                no_implicit_any: true,
                intrinsic: IntrinsicBootstrapOptions {
                    strict_null_checks: true,
                    ..IntrinsicBootstrapOptions::default()
                },
                ..CanonicalCheckerOptions::default()
            },
        );

        context.check_source_file(file).unwrap();

        let diagnostics = context.diagnostics().as_slice();
        assert_eq!(
            diagnostics
                .iter()
                .map(|diagnostic| diagnostic.diagnostic.code())
                .collect::<Vec<_>>(),
            [2450, 7027],
        );
        assert_eq!(node_text(&source, diagnostics[0].node.unwrap()), "Dynamic");
        assert_eq!(
            node_text(&source, diagnostics[1].node.unwrap()),
            "enum Dynamic { First = computed(0), Second = computed(1) }",
        );
        let declaration = diagnostics[1].node.unwrap();
        let (_, bound) = context.file(file).unwrap();
        let enum_owner = bound.symbol(declaration).unwrap();
        let enum_type = context
            .store()
            .declared_type_links(enum_owner)
            .and_then(|links| links.declared_type)
            .unwrap();
        let function = function_symbol(&context, &source, file, "selected");
        let callable = context
            .store()
            .source_callable_type_for_owner(function)
            .unwrap();
        let signature = context
            .store()
            .source_callable_provenance(callable)
            .unwrap()
            .signature;
        assert_eq!(
            context
                .store()
                .signature(signature)
                .and_then(super::super::signatures::Signature::resolved_return_type),
            Some(enum_type),
        );
        assert!(super::super::enums::is_canonical_enum_union(
            context.store(),
            enum_type,
        ));

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn exported_flat_const_objects_preserve_readonly_literal_properties() {
        let source = parsed(concat!(
            "export const ordinary = { new: 'new', delete: 'delete' }; ",
            "export const frozen = ({ ",
            "new: 'new', delete: 'delete', break: 'break', ",
            "count: 1, enabled: true, total: 2n ",
            "}) as const;",
        ));
        let file = FileId::new(8_430);
        let mut context = context_with_module_state(
            &[(file, &source)],
            CanonicalModuleState::External,
            CanonicalCheckerOptions::default(),
        );

        context.check_source_file(file).unwrap();

        let ordinary = variable_initializer(&source, file, "ordinary");
        let assertion = variable_initializer(&source, file, "frozen");
        let NodeData::AsExpression(assertion_data) =
            &source.arena.get(assertion.node).unwrap().data
        else {
            panic!("expected a const assertion")
        };
        let parenthesized = NodeRef::new(source.arena.id(), file, assertion_data.expression);
        let NodeData::ParenthesizedExpression(parenthesized_data) =
            &source.arena.get(parenthesized.node).unwrap().data
        else {
            panic!("expected a parenthesized const object")
        };
        let object = NodeRef::new(source.arena.id(), file, parenthesized_data.expression);
        let frozen = variable_value_type(&context, &source, file, "frozen");
        assert_eq!(resolved_node_type(&context, assertion), frozen);
        assert_eq!(resolved_node_type(&context, parenthesized), frozen);
        assert_eq!(resolved_node_type(&context, object), frozen);
        assert_eq!(
            context
                .type_to_string(object_property_type(&context, ordinary, "new"))
                .unwrap(),
            "string"
        );
        for (name, expected) in [
            ("new", "\"new\""),
            ("delete", "\"delete\""),
            ("break", "\"break\""),
            ("count", "1"),
            ("enabled", "true"),
            ("total", "2n"),
        ] {
            assert_eq!(
                context
                    .type_to_string(object_property_type(&context, object, name))
                    .unwrap(),
                expected
            );
        }
        let TypeData::Object(record) = context.store().type_payload(frozen).unwrap().data() else {
            panic!("expected a frozen object type")
        };
        for symbol in record.structured.properties.as_deref().unwrap_or_default() {
            assert!(
                context
                    .store()
                    .symbol(*symbol)
                    .unwrap()
                    .check_flags()
                    .contains(CheckFlags::READONLY)
            );
        }
        assert_eq!(
            context.type_to_string(frozen).unwrap(),
            concat!(
                "{ readonly new: \"new\"; readonly delete: \"delete\"; ",
                "readonly break: \"break\"; readonly count: 1; ",
                "readonly enabled: true; readonly total: 2n; }",
            )
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn nested_const_assertions_preserve_recursive_readonly_literal_properties() {
        let source = parsed(r"var value = { item: { nested: 1 } } as const;");
        let file = FileId::new(116);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let assertion = variable_initializer(&source, file, "value");
        let NodeData::AsExpression(assertion_data) =
            &source.arena.get(assertion.node).unwrap().data
        else {
            panic!("expected a nested const assertion")
        };
        let outer = NodeRef::new(source.arena.id(), file, assertion_data.expression);
        let inner = object_property_initializer(&source, file, outer, "item");
        let value = variable_value_type(&context, &source, file, "value");
        assert_eq!(resolved_node_type(&context, assertion), value);
        assert_eq!(resolved_node_type(&context, outer), value);
        assert_eq!(
            context
                .type_to_string(object_property_type(&context, inner, "nested"))
                .unwrap(),
            "1",
        );
        assert_eq!(
            context.type_to_string(value).unwrap(),
            "{ readonly item: { readonly nested: 1; }; }",
        );
        for object in [outer, inner] {
            let object_type = resolved_node_type(&context, object);
            let TypeData::Object(record) =
                context.store().type_payload(object_type).unwrap().data()
            else {
                panic!("nested const assertions must retain object types")
            };
            assert!(
                record
                    .structured
                    .properties
                    .as_deref()
                    .unwrap()
                    .iter()
                    .all(|property| {
                        context
                            .store()
                            .symbol(*property)
                            .unwrap()
                            .check_flags()
                            .contains(CheckFlags::READONLY)
                    })
            );
        }
        assert!(context.diagnostics().is_empty());
        assert!(is_type_checked(&context, file));

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn exported_nested_enum_const_objects_survive_readonly_concrete_spreads() {
        let source = parsed(concat!(
            "export enum E { A = 'a', B = 'b' } ",
            "export const A = { item: { a: E.A } } as const; ",
            "export const B = { ...A } as const;",
        ));
        let file = FileId::new(8_531);
        let mut context = context_with_module_state(
            &[(file, &source)],
            CanonicalModuleState::External,
            CanonicalCheckerOptions::default(),
        );

        context.check_source_file(file).unwrap();

        let asserted_object = |name| {
            let assertion = variable_initializer(&source, file, name);
            let NodeData::AsExpression(assertion) = &source.arena.get(assertion.node).unwrap().data
            else {
                panic!("{name} must retain its const assertion")
            };
            NodeRef::new(source.arena.id(), file, assertion.expression)
        };
        let original = asserted_object("A");
        let nested = object_property_initializer(&source, file, original, "item");
        let spread = asserted_object("B");
        let original_type = variable_value_type(&context, &source, file, "A");
        let spread_type = variable_value_type(&context, &source, file, "B");
        assert_eq!(resolved_node_type(&context, original), original_type);
        assert_eq!(resolved_node_type(&context, spread), spread_type);
        assert_eq!(
            object_property_type(&context, spread, "item"),
            object_property_type(&context, original, "item"),
        );
        assert_eq!(
            context
                .type_to_string(object_property_type(&context, nested, "a"))
                .unwrap(),
            "E.A",
        );
        assert_eq!(
            context.type_to_string(original_type).unwrap(),
            "{ readonly item: { readonly a: E.A; }; }",
        );
        assert_eq!(
            context.type_to_string(spread_type).unwrap(),
            "{ readonly item: { readonly a: E.A; }; }",
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn nested_readonly_enum_spreads_keep_last_assignment_and_enum_identity() {
        let source = parsed(concat!(
            "export enum E { A = 'a', B = 'b' } ",
            "export const first = { item: { value: E.A }, shared: E.A } as const; ",
            "export const second = { item: { value: E.B }, shared: E.B } as const; ",
            "export const result = { ...first, ...second, shared: E.A } as const;",
        ));
        let file = FileId::new(8_534);
        let mut context = context_with_module_state(
            &[(file, &source)],
            CanonicalModuleState::External,
            CanonicalCheckerOptions::default(),
        );

        context.check_source_file(file).unwrap();

        let assertion = variable_initializer(&source, file, "result");
        let NodeData::AsExpression(assertion) = &source.arena.get(assertion.node).unwrap().data
        else {
            panic!("the merged result must retain its const assertion")
        };
        let result = NodeRef::new(source.arena.id(), file, assertion.expression);
        let nested = object_property_type(&context, result, "item");
        let nested_property = context
            .store()
            .type_payload(nested)
            .and_then(|record| record.data().structured())
            .and_then(|structured| structured.members)
            .and_then(|members| context.store().symbol_table(members))
            .and_then(|members| members.get_source("value"))
            .unwrap();
        let nested_value = context
            .store()
            .value_symbol_links(nested_property)
            .and_then(|links| links.resolved_type)
            .unwrap();
        assert_eq!(context.type_to_string(nested_value).unwrap(), "E.B");
        assert_eq!(
            context
                .type_to_string(object_property_type(&context, result, "shared"))
                .unwrap(),
            "E.A",
        );
        assert_eq!(
            context
                .type_to_string(variable_value_type(&context, &source, file, "result"))
                .unwrap(),
            "{ readonly item: { readonly value: E.B; }; readonly shared: E.A; }",
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

