    #[test]
    fn shorthand_and_literal_computed_object_properties_publish_and_replay_warm() {
        let source = parsed(concat!(
            "const property: string = \"ok\"; ",
            "const value: any = { property, ['literal']: 1, [2]: 'two', [`template`]: true };",
        ));
        let file = FileId::new(76);
        let mut context = context_with_module_state(
            &[(file, &source)],
            CanonicalModuleState::External,
            CanonicalCheckerOptions::default(),
        );

        context.check_source_file(file).unwrap();

        let object = variable_initializer(&source, file, "value");
        let bootstrap = context.store().intrinsic_bootstrap().unwrap();
        for (name, expected) in [
            ("property", bootstrap.string_type),
            ("literal", bootstrap.number_type),
            ("2", bootstrap.string_type),
            ("template", bootstrap.boolean_type),
        ] {
            assert_eq!(object_property_type(&context, object, name), expected);
        }
        let reads = identifier_expressions(&source, file, "property");
        let [read] = reads.as_slice() else {
            panic!("expected one shorthand property value read")
        };
        let variable = variable_symbol(&context, &source, file, "property");
        assert_eq!(
            context
                .store()
                .symbol_node_links(*read)
                .and_then(|links| links.resolved_symbol),
            Some(variable)
        );
        assert_eq!(resolved_node_type(&context, *read), bootstrap.string_type);

        let mut keys = source
            .arena
            .iter()
            .filter_map(|(_, record)| {
                let NodeData::ComputedPropertyName(name) = &record.data else {
                    return None;
                };
                Some(NodeRef::new(source.arena.id(), file, name.expression))
            })
            .collect::<Vec<_>>();
        keys.sort_unstable_by_key(|key| source.arena.get(key.node).unwrap().range.start);
        let expected_keys = [
            bootstrap.cached_string_literal_type("literal").unwrap(),
            bootstrap
                .cached_number_literal_type(Number::new(2.0))
                .unwrap(),
            bootstrap.cached_string_literal_type("template").unwrap(),
        ];
        assert_eq!(keys.len(), expected_keys.len());
        for (key, regular) in keys.into_iter().zip(expected_keys) {
            let fresh = context.store().fresh_type_of_literal_type(regular).unwrap();
            assert_eq!(resolved_node_type(&context, key), fresh);
            assert_eq!(context.get_type_at_location(key).unwrap(), fresh);
        }
        assert!(context.diagnostics().is_empty());
        assert!(is_type_checked(&context, file));

        let warm = observable_state(&context, file);
        mark_source_unchecked(&mut context, file);
        context.check_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn computed_object_literal_keys_preserve_contextual_errors_and_reject_bad_caches() {
        for malformed in [false, true] {
            let source = parsed(concat!(
                "interface Shape { field: number; } ",
                "const value: Shape = { ['field']: 'wrong' };",
            ));
            let file = FileId::new(9_980);
            let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());
            let key = source
                .arena
                .iter()
                .find_map(|(_, record)| {
                    let NodeData::ComputedPropertyName(name) = &record.data else {
                        return None;
                    };
                    Some(NodeRef::new(source.arena.id(), file, name.expression))
                })
                .unwrap();

            context.check_source_file(file).unwrap();

            let [diagnostic] = context.diagnostics().as_slice() else {
                panic!("the property value must retain its one contextual error")
            };
            assert_eq!(diagnostic.diagnostic.code(), 2322);
            assert_eq!(
                diagnostic.diagnostic.render().unwrap(),
                "Type 'string' is not assignable to type 'number'.",
            );
            let bootstrap = context.store().intrinsic_bootstrap().unwrap();
            let string = bootstrap.string_type;
            let regular = bootstrap.cached_string_literal_type("field").unwrap();
            let fresh = context.store().fresh_type_of_literal_type(regular).unwrap();
            assert_eq!(resolved_node_type(&context, key), fresh);
            assert_eq!(context.get_type_at_location(key).unwrap(), fresh);
            let object = variable_initializer(&source, file, "value");
            assert_eq!(object_property_type(&context, object, "field"), string);
            let warm = observable_state(&context, file);

            context.recheck_source_file(file).unwrap();

            assert_eq!(observable_state(&context, file), warm);
            let poison = TypeNodeLinks {
                resolved_type: Some(if malformed { fresh } else { string }),
                outer_type_parameters: malformed.then(Vec::new),
            };
            assert!(
                context
                    .store_mut_for_test()
                    .set_type_node_links(key, poison.clone())
            );
            mark_source_unchecked(&mut context, file);
            let before = observable_state(&context, file);

            assert!(matches!(
                context.check_source_file(file),
                Err(SourceCheckError::Assertion(
                    SourceAssertionError::InvalidExpressionCache { node, cached, expected }
                )) if node == key && cached == poison.resolved_type && expected == fresh
            ));
            assert_eq!(context.store().type_node_links(key), Some(&poison));
            assert_eq!(observable_state(&context, file), before);
        }
    }

    #[test]
    fn unsupported_object_forms_fail_before_writes() {
        let cases = [
            (
                "const value: any = { method(): string { return ''; } };",
                SourceSyntaxRole::ObjectProperty,
            ),
            (
                "const key = 'property'; const value: any = { [key]: 1 };",
                SourceSyntaxRole::ObjectProperty,
            ),
        ];
        for (index, (text, role)) in cases.into_iter().enumerate() {
            let source = parsed(text);
            let file = FileId::new(72 + u32::try_from(index).unwrap());
            let mut context = context_with_module_state(
                &[(file, &source)],
                CanonicalModuleState::External,
                CanonicalCheckerOptions::default(),
            );
            let before = observable_state(&context, file);

            let result = context.check_source_file(file);
            assert!(
                matches!(
                    result,
                    Err(SourceCheckError::Unsupported(
                        UnsupportedSourceSyntax::Syntax {
                            role: actual,
                            ..
                        }
                    )) if actual == role
                ),
                "source: {text}; result: {result:?}"
            );
            assert_eq!(observable_state(&context, file), before, "source: {text}");
            assert!(context.diagnostics().is_empty());
            assert!(!is_type_checked(&context, file));
        }
    }

    #[test]
    fn expression_literals_use_fresh_booleans_and_null_widening_identity() {
        let source =
            parsed("const yes: any = true; const no: any = false; const none: any = null;");
        let file = FileId::new(43);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());
        let (true_type, regular_true, false_type, regular_false, null_type, null_widening) = {
            let bootstrap = context.store().intrinsic_bootstrap().unwrap();
            (
                bootstrap.true_type,
                bootstrap.regular_true_type,
                bootstrap.false_type,
                bootstrap.regular_false_type,
                bootstrap.null_type,
                bootstrap.null_widening_type,
            )
        };

        let store = context.store_mut_for_test();
        let yes = variable_initializer(&source, file, "yes");
        let no = variable_initializer(&source, file, "no");
        let none = variable_initializer(&source, file, "none");
        assert_eq!(
            expression_type(
                store,
                &PlannedExpression::new(yes, PlannedExpressionKind::Boolean(true)),
                &PreparedExpression::Literal(LiteralTreatment::Fresh),
            ),
            Ok(true_type)
        );
        assert_eq!(
            expression_type(
                store,
                &PlannedExpression::new(no, PlannedExpressionKind::Boolean(false)),
                &PreparedExpression::Literal(LiteralTreatment::Fresh),
            ),
            Ok(false_type)
        );
        assert_eq!(
            expression_type(
                store,
                &PlannedExpression::new(none, PlannedExpressionKind::Null),
                &PreparedExpression::Literal(LiteralTreatment::Identity),
            ),
            Ok(null_widening)
        );
        assert_ne!(true_type, regular_true);
        assert_ne!(false_type, regular_false);
        assert_ne!(null_widening, null_type);
    }

    #[test]
    fn regular_expression_literals_reuse_global_identity_across_expression_positions() {
        let library = parsed("interface RegExp {} interface Array<T> {}");
        let source = parsed(concat!(
            "const direct = /regexp/g; ",
            "const wrapped = ((/nested/i)); ",
            "const asserted: any = (<any>/cast/g); ",
            "const values: RegExp[] = [/one/, /two/g]; ",
            "declare function accept(value: RegExp): RegExp; ",
            "const result = accept(/argument/g); ",
            "const frozen = { pattern: /readonly/g } as const; ",
            "(<any>/statement/g); ",
            "/standalone/;",
        ));
        let library_file = FileId::new(9_760);
        let file = FileId::new(9_761);
        let mut context = context_with_default_library_files(
            &[(library_file, &library), (file, &source)],
            &[library_file],
            CanonicalCheckerOptions::default(),
        );
        let regexp = context.global_types().regexp_type;
        let owner = global_symbol(&context, "RegExp");
        assert_eq!(
            context
                .store()
                .declared_type_links(owner)
                .and_then(|links| links.declared_type),
            Some(regexp),
        );

        context.check_source_file(file).unwrap();

        let literals = source
            .arena
            .iter()
            .filter_map(|(node, record)| {
                (record.kind == SyntaxKind::RegularExpressionLiteral).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .collect::<Vec<_>>();
        assert_eq!(literals.len(), 9);
        for literal in literals {
            assert_eq!(resolved_node_type(&context, literal), regexp);
        }
        for name in ["direct", "wrapped", "result"] {
            assert_eq!(variable_value_type(&context, &source, file, name), regexp);
        }

        let any = context.store().intrinsic_bootstrap().unwrap().any_type;
        assert_eq!(
            variable_value_type(&context, &source, file, "asserted"),
            any,
        );
        let assertions = source
            .arena
            .iter()
            .filter_map(|(node, record)| {
                (record.kind == SyntaxKind::TypeAssertionExpression).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .collect::<Vec<_>>();
        assert_eq!(assertions.len(), 2);
        for assertion in assertions {
            assert_eq!(resolved_node_type(&context, assertion), any);
            assert_eq!(
                context.store().assertion_links(assertion),
                Some(&AssertionLinks {
                    expr_type: Some(regexp),
                }),
            );
        }

        for (node, record) in source.arena.iter() {
            if record.kind != SyntaxKind::ParenthesizedExpression {
                continue;
            }
            let wrapper = NodeRef::new(source.arena.id(), file, node);
            let expected = if node_text(&source, wrapper).contains("<any>") {
                any
            } else {
                regexp
            };
            assert_eq!(resolved_node_type(&context, wrapper), expected);
        }

        let values = variable_initializer(&source, file, "values");
        for element in array_elements(&source, file, values) {
            assert_eq!(resolved_node_type(&context, element), regexp);
        }
        for type_ in [
            resolved_node_type(&context, values),
            variable_value_type(&context, &source, file, "values"),
        ] {
            assert_eq!(
                context
                    .store()
                    .canonical_array_reference(context.global_types(), type_)
                    .unwrap()
                    .unwrap()
                    .element_type,
                regexp,
            );
        }

        let frozen = variable_initializer(&source, file, "frozen");
        let NodeData::AsExpression(assertion) = &source.arena.get(frozen.node).unwrap().data else {
            panic!("expected a const assertion")
        };
        let object = NodeRef::new(source.arena.id(), file, assertion.expression);
        assert_eq!(object_property_type(&context, object, "pattern"), regexp);
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn regular_expression_literals_preserve_missing_and_malformed_global_fallbacks() {
        for (index, declaration) in [
            None,
            Some("interface RegExp<T> {}"),
            Some("type RegExp = string;"),
        ]
        .into_iter()
        .enumerate()
        {
            let source = parsed("const value = /fallback/g; (<any>/statement/g);");
            let library = declaration.map(parsed);
            let offset = u32::try_from(index).unwrap() * 2;
            let file = FileId::new(9_762 + offset);
            let library_file = FileId::new(9_763 + offset);
            let mut files = vec![(file, &source)];
            let mut default_library_files = Vec::new();
            if let Some(library) = library.as_ref() {
                files.push((library_file, library));
                default_library_files.push(library_file);
            }
            let mut context = context_with_default_library_files(
                &files,
                &default_library_files,
                CanonicalCheckerOptions::default(),
            );
            let fallback = context
                .store()
                .intrinsic_bootstrap()
                .unwrap()
                .empty_object_type;
            assert_eq!(context.global_types().regexp_type, fallback);

            context.check_source_file(file).unwrap();

            assert_eq!(
                variable_value_type(&context, &source, file, "value"),
                fallback,
            );
            for (node, record) in source.arena.iter() {
                if record.kind == SyntaxKind::RegularExpressionLiteral {
                    assert_eq!(
                        resolved_node_type(&context, NodeRef::new(source.arena.id(), file, node),),
                        fallback,
                    );
                }
            }
            assert!(context.diagnostics().is_empty());

            let warm = observable_state(&context, file);
            context.recheck_source_file(file).unwrap();
            assert_eq!(observable_state(&context, file), warm);
        }
    }

    #[test]
    fn poisoned_regular_expression_cache_rejects_planning_before_publication() {
        let library = parsed("interface RegExp {}");
        let source = parsed("const first = /first/; const later = /poisoned/g;");
        let library_file = FileId::new(9_768);
        let file = FileId::new(9_769);
        let mut context = context_with_default_library_files(
            &[(library_file, &library), (file, &source)],
            &[library_file],
            CanonicalCheckerOptions::default(),
        );
        let first = variable_initializer(&source, file, "first");
        let later = variable_initializer(&source, file, "later");
        let first_symbol = variable_symbol(&context, &source, file, "first");
        let later_symbol = variable_symbol(&context, &source, file, "later");
        let expected = context.global_types().regexp_type;
        let poison = context.store().intrinsic_bootstrap().unwrap().number_type;
        assert_ne!(poison, expected);
        assert!(context.store_mut_for_test().set_type_node_links(
            later,
            TypeNodeLinks {
                resolved_type: Some(poison),
                ..TypeNodeLinks::default()
            },
        ));
        let before = observable_state(&context, file);
        let error = SourceCheckError::Assertion(SourceAssertionError::InvalidExpressionCache {
            node: later,
            cached: Some(poison),
            expected,
        });

        for _ in 0..2 {
            assert_eq!(context.check_source_file(file), Err(error));
            assert_eq!(observable_state(&context, file), before);
            assert!(context.store().type_node_links(first).is_none());
            assert!(context.store().value_symbol_links(first_symbol).is_none());
            assert!(context.store().value_symbol_links(later_symbol).is_none());
            assert!(context.diagnostics().is_empty());
            assert!(!is_type_checked(&context, file));
        }

        assert!(
            context
                .store_mut_for_test()
                .set_type_node_links(later, TypeNodeLinks::default())
        );
        context.check_source_file(file).unwrap();
        assert_eq!(resolved_node_type(&context, first), expected);
        assert_eq!(resolved_node_type(&context, later), expected);
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
