    #[test]
    fn array_sort_contextualizes_binder_owned_tuple_callback_elements() {
        let library = parsed(concat!(
            "interface Array<T> { ",
            "sort(compare: (first: [string, any], second: [string, any]) => number): ",
            "[string, any][]; ",
            "} interface ReadonlyArray<T> {}",
        ));
        let source = parsed(concat!(
            "declare const values: [string, any][]; ",
            "const sorted = values.sort(([firstKey, firstValue], ",
            "[secondKey, secondValue]) => 0);",
        ));
        let library_file = FileId::new(9_492);
        let source_file = FileId::new(9_493);
        let mut context = context(
            &[(library_file, &library), (source_file, &source)],
            CanonicalCheckerOptions {
                no_implicit_any: true,
                ..CanonicalCheckerOptions::default()
            },
        );
        let method = library
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::MethodSignature).then_some(NodeRef::new(
                    library.arena.id(),
                    library_file,
                    node,
                ))
            })
            .unwrap();
        let NodeData::MethodSignatureDeclaration(method_data) =
            &library.arena.get(method.node).unwrap().data
        else {
            panic!("the global array retains its real sort method declaration")
        };
        let parameter = method_data.parameters.nodes[0];
        let NodeData::ParameterDeclaration(parameter_data) =
            &library.arena.get(parameter).unwrap().data
        else {
            panic!("the sort method retains its comparator parameter")
        };
        let callback_type = NodeRef::new(
            library.arena.id(),
            library_file,
            parameter_data.type_.unwrap(),
        );
        context.get_type_from_type_node(callback_type).unwrap();

        context.check_source_file(library_file).unwrap();
        context.check_source_file(source_file).unwrap();

        assert!(context.diagnostics().is_empty());
        assert_eq!(
            context
                .type_to_string(variable_value_type(
                    &context,
                    &source,
                    source_file,
                    "sorted"
                ))
                .unwrap(),
            "[string, any][]",
        );
        let bootstrap = context.store().intrinsic_bootstrap().unwrap();
        let (_, bound) = context.file(source_file).unwrap();
        for (node, record) in source.arena.iter() {
            let NodeData::BindingElement(binding) = &record.data else {
                continue;
            };
            let name = binding.name.unwrap();
            let NodeData::Identifier(identifier) = &source.arena.get(name).unwrap().data else {
                panic!("sort tuple binding elements must retain identifier names")
            };
            let element = NodeRef::new(source.arena.id(), source_file, node);
            let symbol = bound.symbol(element).unwrap();
            let expected = if identifier.text.ends_with("Key") {
                bootstrap.string_type
            } else {
                bootstrap.any_type
            };
            assert_eq!(
                context
                    .store()
                    .value_symbol_links(symbol)
                    .and_then(|links| links.resolved_type),
                Some(expected),
            );
        }

        let warm = observable_state(&context, source_file);
        context.recheck_source_file(source_file).unwrap();
        assert_eq!(observable_state(&context, source_file), warm);
    }

    #[test]
    fn zero_parameter_callback_targets_preserve_return_and_extra_parameter_diagnostics() {
        let source = parsed(concat!(
            "function accept(callback: () => number): void {}\n",
            "accept(() => {});\n",
            "accept((first, second, third, fourth) => {});\n",
            "accept(value => 1 +\n  2);\n",
        ));
        let file = FileId::new(8_374);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let rendered = context
            .diagnostics()
            .as_slice()
            .iter()
            .map(|diagnostic| diagnostic.diagnostic.render().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(
            rendered,
            [
                concat!(
                    "Argument of type '() => void' is not assignable to parameter ",
                    "of type '() => number'.\n",
                    "  Type 'void' is not assignable to type 'number'.",
                ),
                concat!(
                    "Argument of type '(first: any, second: any, third: any, fourth: any) ",
                    "=> void' is not assignable to parameter of type '() => number'.\n",
                    "  Target signature provides too few arguments. ",
                    "Expected 4 or more, but got 0.",
                ),
                concat!(
                    "Argument of type '(value: any) => number' is not assignable to ",
                    "parameter of type '() => number'.\n",
                    "  Target signature provides too few arguments. ",
                    "Expected 1 or more, but got 0.",
                ),
            ],
        );

        let mut arrows = source
            .arena
            .iter()
            .filter_map(|(node, record)| {
                (record.kind == SyntaxKind::ArrowFunction).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .collect::<Vec<_>>();
        arrows.sort_by_key(|arrow| source.arena.get(arrow.node).unwrap().range.start);
        let (_, bound) = context.file(file).unwrap();
        let bootstrap = context.store().intrinsic_bootstrap().unwrap();
        for (arrow, (expected_count, expected_return)) in arrows.into_iter().zip([
            (0, bootstrap.void_type),
            (4, bootstrap.void_type),
            (1, bootstrap.number_type),
        ]) {
            let owner = bound.symbol(arrow).unwrap();
            let callable = context
                .store()
                .source_callable_type_for_owner(owner)
                .unwrap();
            let provenance = context
                .store()
                .source_callable_provenance(callable)
                .unwrap();
            assert!(provenance.contextual_target.is_none());
            let signature = context.store().signature(provenance.signature).unwrap();
            assert_eq!(signature.parameters().len(), expected_count);
            assert_eq!(signature.resolved_return_type(), Some(expected_return));
            for parameter in signature.parameters() {
                assert_eq!(
                    context
                        .store()
                        .value_symbol_links(*parameter)
                        .and_then(|links| links.resolved_type),
                    Some(bootstrap.any_type),
                );
            }
        }

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn arrow_line_terminator_diagnostics_use_only_the_exact_arrow_token() {
        let source = parsed(concat!(
            "function accept(callback: () => number): void {}\n",
            "accept(()\n    => {});\n",
            "accept((first,\n    second) => {});\n",
            "accept(() /* same line */ => {});\n",
            "accept(() /* crossed\n    */ => {});\n",
        ));
        let file = FileId::new(8_375);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let grammar = context
            .diagnostics()
            .as_slice()
            .iter()
            .filter(|diagnostic| diagnostic.diagnostic.code() == 1200)
            .collect::<Vec<_>>();
        assert_eq!(grammar.len(), 2);
        for diagnostic in grammar {
            let node = diagnostic.node.expect("TS1200 retains its arrow token");
            assert_eq!(
                source.arena.get(node.node).unwrap().kind,
                SyntaxKind::EqualsGreaterThanToken
            );
            assert_eq!(node_text(&source, node), "=>");
            assert_eq!(
                diagnostic.diagnostic.render().unwrap(),
                "Line terminator not permitted before arrow."
            );
        }
        assert_eq!(
            context
                .diagnostics()
                .as_slice()
                .iter()
                .filter(|diagnostic| diagnostic.diagnostic.code() == 2345)
                .count(),
            4,
        );

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn object_property_arrows_publish_distinct_callables_and_widen_other_properties() {
        let source = parsed(concat!(
            "const captured = 1; ",
            "var resolve = { ",
            "id: /*! @ngInject */ (details: any) => details.id, ",
            "label: 'hello', ",
            "wrapped: ((details: any) => details.id), ",
            "other: (details: any) => details.id, ",
            "}; const retained = captured;",
        ));
        let file = FileId::new(8_414);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let object = variable_initializer(&source, file, "resolve");
        let bootstrap = context.store().intrinsic_bootstrap().unwrap();
        let any = bootstrap.any_type;
        assert_eq!(
            object_property_type(&context, object, "label"),
            bootstrap.string_type
        );
        assert_eq!(
            variable_value_type(&context, &source, file, "retained"),
            variable_value_type(&context, &source, file, "captured")
        );

        let (_, bound) = context.file(file).unwrap();
        let mut callables = HashSet::new();
        for name in ["id", "wrapped", "other"] {
            let mut arrow = object_property_initializer(&source, file, object, name);
            while let NodeData::ParenthesizedExpression(parenthesized) =
                &source.arena.get(arrow.node).unwrap().data
            {
                arrow = NodeRef::new(source.arena.id(), file, parenthesized.expression);
            }
            let owner = bound.symbol(arrow).unwrap();
            let callable = context
                .store()
                .source_callable_type_for_owner(owner)
                .unwrap();
            assert!(callables.insert(callable));
            assert_eq!(resolved_node_type(&context, arrow), callable);
            assert_eq!(object_property_type(&context, object, name), callable);
            let signature = context
                .store()
                .source_callable_provenance(callable)
                .unwrap()
                .signature;
            assert_eq!(
                context
                    .store()
                    .signature(signature)
                    .unwrap()
                    .resolved_return_type(),
                Some(any)
            );
        }
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        mark_source_unchecked(&mut context, file);
        context.check_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

