    #[test]
    fn malformed_object_cache_rejects_property_arrows_before_publication() {
        let source = parsed("var resolve = { id: (details: any) => details.id };");
        let file = FileId::new(8_415);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());
        let object = variable_initializer(&source, file, "resolve");
        let variable = variable_symbol(&context, &source, file, "resolve");
        let arrow = object_property_initializer(&source, file, object, "id");
        let owner = context.file(file).unwrap().1.symbol(arrow).unwrap();
        let number = context.store().intrinsic_bootstrap().unwrap().number_type;
        assert!(context.store_mut_for_test().set_type_node_links(
            object,
            TypeNodeLinks {
                resolved_type: Some(number),
                ..TypeNodeLinks::default()
            },
        ));
        let before = observable_state(&context, file);

        assert!(matches!(
            context.check_source_file(file),
            Err(SourceCheckError::ObjectLiteral(
                SourceObjectLiteralError::InvalidCache { node, .. }
            )) if node == object
        ));
        assert_eq!(observable_state(&context, file), before);
        assert!(context.store().value_symbol_links(variable).is_none());
        assert!(
            context
                .store()
                .source_callable_type_for_owner(owner)
                .is_none()
        );
        assert!(context.diagnostics().is_empty());
    }

    #[test]
    fn contextual_array_assertions_retain_deferred_comparisons_and_replay_warm() {
        let library = parsed("interface Array<T> {}");
        let library_file = FileId::new(8_416);
        let cases = [
            ("var foo: { id: number }[] = [<{ id: number }>({})];", None),
            (
                "var foo: { id: number }[] = [<{ id: number }>('bad')];",
                Some(2352),
            ),
        ];

        for (index, (text, expected_diagnostic)) in cases.into_iter().enumerate() {
            let source = parsed(text);
            let file = FileId::new(8_417 + u32::try_from(index).unwrap());
            let mut context = context(
                &[(library_file, &library), (file, &source)],
                CanonicalCheckerOptions::default(),
            );

            context.check_source_file(file).unwrap();

            let array = variable_initializer(&source, file, "foo");
            let elements = array_elements(&source, file, array);
            let [assertion] = elements.as_slice() else {
                panic!("expected one asserted array element")
            };
            let NodeData::TypeAssertion(assertion_data) =
                &source.arena.get(assertion.node).unwrap().data
            else {
                panic!("expected an asserted array element")
            };
            let operand = NodeRef::new(source.arena.id(), file, assertion_data.expression);
            assert_eq!(
                context.store().assertion_links(*assertion),
                Some(&AssertionLinks {
                    expr_type: Some(resolved_node_type(&context, operand)),
                })
            );
            let source_ref = context.source_file(file).unwrap();
            assert_eq!(
                context
                    .store()
                    .source_file_links(source_ref)
                    .unwrap()
                    .deferred_nodes
                    .iter()
                    .copied()
                    .collect::<Vec<_>>(),
                [*assertion]
            );
            assert_eq!(
                context
                    .diagnostics()
                    .as_slice()
                    .iter()
                    .map(|diagnostic| diagnostic.diagnostic.code())
                    .collect::<Vec<_>>(),
                expected_diagnostic.into_iter().collect::<Vec<_>>()
            );

            let warm = observable_state(&context, file);
            mark_source_unchecked(&mut context, file);
            context.check_source_file(file).unwrap();
            assert_eq!(observable_state(&context, file), warm);
        }
    }

    #[test]
    fn direct_source_arrows_infer_exact_callable_identity_and_retry_warm() {
        let source = parsed(concat!(
            "const f = (value: string, optional?: number): string => value; ",
            "const forward = (): string => later; ",
            "const later = 'ok'; ",
            "const copy = f;",
        ));
        let file = FileId::new(308);
        let mut context = context(
            &[(file, &source)],
            CanonicalCheckerOptions {
                intrinsic: IntrinsicBootstrapOptions {
                    strict_null_checks: true,
                    exact_optional_property_types: false,
                },
                ..CanonicalCheckerOptions::default()
            },
        );

        context.check_source_file(file).unwrap();

        let variable = variable_symbol(&context, &source, file, "f");
        let declaration = variable_declaration(&source, file, "f");
        let arrow = variable_initializer(&source, file, "f");
        let (_, bound) = context.file(file).unwrap();
        let owner = bound.symbol(arrow).unwrap();
        assert_ne!(variable, owner);
        assert_eq!(bound.symbol(declaration), Some(variable));
        let callable = variable_value_type(&context, &source, file, "f");
        assert_eq!(
            variable_value_type(&context, &source, file, "copy"),
            callable
        );
        assert_eq!(
            context.store().source_callable_type_for_owner(owner),
            Some(callable)
        );
        assert_eq!(
            context
                .store()
                .value_symbol_links(owner)
                .and_then(|links| links.resolved_type),
            Some(callable)
        );
        let provenance = context
            .store()
            .source_callable_provenance(callable)
            .unwrap();
        assert_eq!(provenance.declaration, arrow);
        assert_eq!(provenance.owner_symbol, owner);
        let signature = context.store().signature(provenance.signature).unwrap();
        assert!(signature.resolved_return_type().is_some());
        let [value, optional] = signature.parameters() else {
            panic!("expected two arrow parameters")
        };
        assert!([*value, *optional].iter().all(|parameter| {
            context
                .store()
                .value_symbol_links(*parameter)
                .and_then(|links| links.resolved_type)
                .is_some()
        }));
        let value_reads = identifier_expressions(&source, file, "value");
        let [value_read] = value_reads.as_slice() else {
            panic!("expected one arrow parameter read")
        };
        assert_eq!(
            context
                .store()
                .symbol_node_links(*value_read)
                .and_then(|links| links.resolved_symbol),
            Some(*value)
        );
        assert!(context.diagnostics().is_empty());
        assert!(is_type_checked(&context, file));

        let warm = observable_state(&context, file);
        mark_source_unchecked(&mut context, file);
        context.check_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
        assert_eq!(variable_value_type(&context, &source, file, "f"), callable);
        assert!(context.diagnostics().is_empty());
    }

    #[test]
    fn anonymous_function_expressions_preserve_callable_identity_and_infer_returns() {
        let source = parsed(concat!(
            "const empty = function () {}; ",
            "const returned = function () { return 42; }; ",
            "const copy = returned; ",
            "const result = returned();",
        ));
        let file = FileId::new(8_700);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let bootstrap = context.store().intrinsic_bootstrap().unwrap();
        let void = bootstrap.void_type;
        let number = bootstrap.number_type;
        for (name, expected_return) in [("empty", void), ("returned", number)] {
            let expression = variable_initializer(&source, file, name);
            let variable = variable_symbol(&context, &source, file, name);
            let (_, bound) = context.file(file).unwrap();
            let owner = bound.symbol(expression).unwrap();
            let callable = variable_value_type(&context, &source, file, name);

            assert_ne!(owner, variable);
            assert_eq!(
                context.store().source_node_kind(expression),
                Some(SyntaxKind::FunctionExpression),
            );
            assert_eq!(
                context.store().source_callable_type_for_owner(owner),
                Some(callable),
            );
            assert_eq!(resolved_node_type(&context, expression), callable);
            let provenance = context
                .store()
                .source_callable_provenance(callable)
                .unwrap();
            assert_eq!(provenance.family, SourceCallableFamily::ArrowFunction);
            assert_eq!(provenance.declaration, expression);
            assert_eq!(provenance.owner_symbol, owner);
            assert_eq!(
                context
                    .store()
                    .signature(provenance.signature)
                    .unwrap()
                    .resolved_return_type(),
                Some(expected_return),
            );
            assert!(matches!(
                validate_stored_source_callable(context.store(), callable),
                StoredSourceCallableValidation::Valid(_)
            ));
            assert_eq!(
                context.type_to_string(callable).unwrap(),
                if expected_return == void {
                    "() => void"
                } else {
                    "() => number"
                },
            );
        }
        assert_eq!(
            variable_value_type(&context, &source, file, "copy"),
            variable_value_type(&context, &source, file, "returned"),
        );
        assert_eq!(
            variable_value_type(&context, &source, file, "result"),
            number,
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn parenthesized_and_standalone_function_expressions_capture_prior_values() {
        let source = parsed(concat!(
            "const captured = 1; ",
            "const retained = ((function () { return captured; })); ",
            "((function () { return captured; }));",
        ));
        let file = FileId::new(8_709);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let captured = variable_symbol(&context, &source, file, "captured");
        let number = context.store().intrinsic_bootstrap().unwrap().number_type;
        let expressions = source
            .arena
            .iter()
            .filter_map(|(node, record)| {
                (record.kind == SyntaxKind::FunctionExpression).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .collect::<Vec<_>>();
        assert_eq!(expressions.len(), 2);
        for expression in expressions {
            let (_, bound) = context.file(file).unwrap();
            let owner = bound.symbol(expression).unwrap();
            let callable = context
                .store()
                .source_callable_type_for_owner(owner)
                .unwrap();
            let signature = context
                .store()
                .source_callable_provenance(callable)
                .unwrap()
                .signature;
            assert_eq!(resolved_node_type(&context, expression), callable);
            assert_eq!(
                context
                    .store()
                    .signature(signature)
                    .unwrap()
                    .resolved_return_type(),
                Some(number),
            );
        }
        for read in identifier_expressions(&source, file, "captured") {
            assert_eq!(
                context
                    .store()
                    .symbol_node_links(read)
                    .and_then(|links| links.resolved_symbol),
                Some(captured),
            );
        }
        assert_eq!(
            context
                .type_to_string(variable_value_type(&context, &source, file, "retained"))
                .unwrap(),
            "() => number",
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn standalone_function_expressions_capture_exact_for_in_lexical_bindings() {
        let source = parsed(concat!(
            "const key = 1; ",
            "for (let key in { first: 1 }) { ",
            "(function () { return key; }); ",
            "(function () { return key + key; }); ",
            "} ",
            "for (const key in { second: 2 }) { ",
            "(function () { return key; }); ",
            "} ",
            "key;",
        ));
        let file = FileId::new(8_710);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let (_, bound) = context.file(file).unwrap();
        let mut loops = source
            .arena
            .iter()
            .filter_map(|(node, record)| {
                let NodeData::ForInOrOfStatement(iteration) = &record.data else {
                    return None;
                };
                if record.kind != SyntaxKind::ForInStatement {
                    return None;
                }
                let NodeData::VariableDeclarationList(bindings) =
                    &source.arena.get(iteration.initializer)?.data
                else {
                    return None;
                };
                let declaration = NodeRef::new(
                    source.arena.id(),
                    file,
                    *bindings.declarations.nodes.first()?,
                );
                Some((
                    NodeRef::new(source.arena.id(), file, node),
                    bound.symbol(declaration)?,
                ))
            })
            .collect::<Vec<_>>();
        loops.sort_unstable_by_key(|(node, _)| source.arena.get(node.node).unwrap().range.start);
        let [(_, first), (_, second)] = loops.as_slice() else {
            panic!("expected the let and const loop bindings")
        };
        let string = context.store().intrinsic_bootstrap().unwrap().string_type;
        for (node, record) in source.arena.iter() {
            if record.kind != SyntaxKind::FunctionExpression {
                continue;
            }
            let expression = NodeRef::new(source.arena.id(), file, node);
            let callable = resolved_node_type(&context, expression);
            let signature = context
                .store()
                .source_callable_provenance(callable)
                .unwrap()
                .signature;
            assert_eq!(
                context
                    .store()
                    .signature(signature)
                    .unwrap()
                    .resolved_return_type(),
                Some(string),
            );
        }
        let mut reads = identifier_expressions(&source, file, "key");
        reads.sort_unstable_by_key(|node| source.arena.get(node.node).unwrap().range.start);
        let [first_read, binary_left, binary_right, second_read, trailing] = reads.as_slice()
        else {
            panic!("expected four captured reads and one trailing top-level read")
        };
        for (read, expected) in [
            (*first_read, *first),
            (*binary_left, *first),
            (*binary_right, *first),
            (*second_read, *second),
        ] {
            assert_eq!(
                context
                    .store()
                    .symbol_node_links(read)
                    .and_then(|links| links.resolved_symbol),
                Some(expected),
            );
            assert_eq!(resolved_node_type(&context, read), string);
        }
        assert_eq!(
            context
                .store()
                .symbol_node_links(*trailing)
                .and_then(|links| links.resolved_symbol),
            Some(variable_symbol(&context, &source, file, "key")),
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn immediately_invoked_closures_publish_their_exact_callable_signatures() {
        let source = parsed(concat!(
            "const captured = 1; ",
            "(function () { return captured; })(); ",
            "const result = ((function () { return captured; }))(); ",
            "const arrow = (() => captured)();",
        ));
        let file = FileId::new(8_711);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let number = context.store().intrinsic_bootstrap().unwrap().number_type;
        let calls = source
            .arena
            .iter()
            .filter_map(|(node, record)| {
                let NodeData::CallExpression(call) = &record.data else {
                    return None;
                };
                Some((
                    NodeRef::new(source.arena.id(), file, node),
                    NodeRef::new(source.arena.id(), file, call.expression),
                ))
            })
            .collect::<Vec<_>>();
        assert_eq!(calls.len(), 3);
        for (call, callee) in calls {
            let callable = resolved_node_type(&context, callee);
            let signature = context
                .store()
                .source_callable_provenance(callable)
                .unwrap()
                .signature;
            assert_eq!(resolved_node_type(&context, call), number);
            assert_eq!(
                context
                    .store()
                    .signature_links(call)
                    .and_then(|links| links.resolved_signature.signature()),
                Some(signature),
            );
        }
        assert_eq!(
            variable_value_type(&context, &source, file, "result"),
            number
        );
        assert_eq!(
            variable_value_type(&context, &source, file, "arrow"),
            number
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

