    #[test]
    fn direct_arrow_expandos_publish_binder_properties_and_replay_warm() {
        let source = parsed("const foo = () => {}\nfoo.bar = 42\nexport {}");
        let file = FileId::new(8_410);
        let mut context = context_with_module_state(
            &[(file, &source)],
            CanonicalModuleState::External,
            CanonicalCheckerOptions::default(),
        );

        context.check_source_file(file).unwrap();

        let arrow = variable_initializer(&source, file, "foo");
        let variable = variable_symbol(&context, &source, file, "foo");
        let (left, right) = assignment_parts(&source, file, 0);
        let expression = NodeRef::new(
            source.arena.id(),
            file,
            source.arena.get(left.node).unwrap().parent.unwrap(),
        );
        let NodeData::PropertyAccessExpression(access) = &source.arena.get(left.node).unwrap().data
        else {
            panic!("expected foo.bar property access")
        };
        let receiver = NodeRef::new(source.arena.id(), file, access.expression);
        let (_, bound) = context.file(file).unwrap();
        let owner = bound.symbol(arrow).unwrap();
        let property = bound.symbol(expression).unwrap();
        let owner_record = context.store().symbol(owner).unwrap();
        assert_eq!(
            owner_record
                .exports()
                .and_then(|exports| context.store().symbol_table(exports))
                .and_then(|exports| exports.get_source("bar")),
            Some(property),
        );
        let property_record = context.store().symbol(property).unwrap();
        assert_eq!(
            property_record.flags(),
            SymbolFlags::PROPERTY | SymbolFlags::ASSIGNMENT,
        );
        assert_eq!(property_record.parent(), Some(owner));
        assert_eq!(property_record.declarations(), Some(&[expression][..]));
        assert_eq!(property_record.value_declaration(), Some(expression));

        let callable = variable_value_type(&context, &source, file, "foo");
        assert_eq!(
            context.store().source_callable_type_for_owner(owner),
            Some(callable)
        );
        assert_eq!(resolved_node_type(&context, receiver), callable);
        assert_eq!(
            context
                .store()
                .symbol_node_links(receiver)
                .and_then(|links| links.resolved_symbol),
            Some(variable),
        );
        let provenance = context
            .store()
            .source_callable_provenance(callable)
            .unwrap();
        assert_eq!(provenance.declaration, arrow);
        assert_eq!(provenance.owner_symbol, owner);
        assert_eq!(
            context
                .store()
                .signature(provenance.signature)
                .and_then(super::super::signatures::Signature::resolved_return_type),
            Some(context.store().intrinsic_bootstrap().unwrap().void_type),
        );

        let number = context.store().intrinsic_bootstrap().unwrap().number_type;
        assert_eq!(
            context
                .store()
                .value_symbol_links(property)
                .and_then(|links| links.resolved_type),
            Some(number),
        );
        assert_eq!(resolved_node_type(&context, left), number);
        assert_eq!(
            resolved_node_type(&context, expression),
            resolved_node_type(&context, right),
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn javascript_arrow_expandos_preserve_properties_across_variable_bindings() {
        for (index, source_text) in [
            "var callback = () => {}; callback.value = 1; const copied = callback.value;",
            "let callback = () => {}; callback.value = 1; const copied = callback.value;",
            "const callback = () => {}; callback.value = 1; const copied = callback.value;",
        ]
        .into_iter()
        .enumerate()
        {
            let source = parse_javascript_source_file(source_text);
            assert!(source.diagnostics.is_empty(), "{:?}", source.diagnostics);
            let file = FileId::new(8_450 + u32::try_from(index).unwrap());
            let mut context = javascript_context(file, &source, CanonicalCheckerOptions::default());

            context.check_source_file(file).unwrap();

            let arrow = variable_initializer(&source, file, "callback");
            let variable = variable_symbol(&context, &source, file, "callback");
            let (left, right) = assignment_parts(&source, file, 0);
            let expression = NodeRef::new(
                source.arena.id(),
                file,
                source.arena.get(left.node).unwrap().parent.unwrap(),
            );
            let NodeData::PropertyAccessExpression(access) =
                &source.arena.get(left.node).unwrap().data
            else {
                panic!("expected callback.value property access")
            };
            let receiver = NodeRef::new(source.arena.id(), file, access.expression);
            let (_, bound) = context.file(file).unwrap();
            let owner = bound.symbol(arrow).unwrap();
            let property = bound.symbol(expression).unwrap();
            assert_eq!(
                context
                    .store()
                    .symbol(owner)
                    .and_then(ts_binder::semantic::Symbol::exports)
                    .and_then(|exports| context.store().symbol_table(exports))
                    .and_then(|exports| exports.get_source("value")),
                Some(property),
            );
            assert_eq!(
                context.store().symbol(property).unwrap().flags(),
                SymbolFlags::PROPERTY | SymbolFlags::ASSIGNMENT,
            );

            let callable = variable_value_type(&context, &source, file, "callback");
            assert_eq!(
                context.store().source_callable_type_for_owner(owner),
                Some(callable),
            );
            assert_eq!(resolved_node_type(&context, receiver), callable);
            assert_eq!(
                context
                    .store()
                    .symbol_node_links(receiver)
                    .and_then(|links| links.resolved_symbol),
                Some(variable),
            );

            let number = context.store().intrinsic_bootstrap().unwrap().number_type;
            assert_eq!(
                context
                    .store()
                    .value_symbol_links(property)
                    .and_then(|links| links.resolved_type),
                Some(number),
            );
            assert_eq!(resolved_node_type(&context, left), number);
            assert_eq!(
                resolved_node_type(&context, expression),
                resolved_node_type(&context, right),
            );
            assert_eq!(
                variable_value_type(&context, &source, file, "copied"),
                number,
            );
            let copied = variable_initializer(&source, file, "copied");
            assert_eq!(
                context
                    .store()
                    .symbol_node_links(copied)
                    .and_then(|links| links.resolved_symbol),
                Some(property),
            );
            assert!(context.diagnostics().is_empty());

            let warm = observable_state(&context, file);
            context.recheck_source_file(file).unwrap();
            assert_eq!(observable_state(&context, file), warm);
        }
    }

    #[test]
    fn direct_function_expandos_preserve_properties_and_source_callable_identity() {
        for (index, javascript) in [false, true].into_iter().enumerate() {
            let source_text = if javascript {
                "function work() {} work.value = 1; const copied = work.value;"
            } else {
                "function work() {} work.value = 1; const copied = work.value; export {};"
            };
            let source = if javascript {
                parse_javascript_source_file(source_text)
            } else {
                parsed(source_text)
            };
            assert!(source.diagnostics.is_empty(), "{:?}", source.diagnostics);
            let file = FileId::new(8_460 + u32::try_from(index).unwrap());
            let mut context = if javascript {
                javascript_context(file, &source, CanonicalCheckerOptions::default())
            } else {
                context_with_module_state(
                    &[(file, &source)],
                    CanonicalModuleState::External,
                    CanonicalCheckerOptions::default(),
                )
            };

            context.check_source_file(file).unwrap();

            let owner = function_symbol(&context, &source, file, "work");
            let callable = context
                .store()
                .value_symbol_links(owner)
                .and_then(|links| links.resolved_type)
                .unwrap();
            assert_eq!(
                context.store().source_callable_type_for_owner(owner),
                Some(callable),
            );
            assert!(matches!(
                validate_stored_source_callable(context.store(), callable),
                StoredSourceCallableValidation::Valid(_)
            ));
            let (left, right) = assignment_parts(&source, file, 0);
            let expression = NodeRef::new(
                source.arena.id(),
                file,
                source.arena.get(left.node).unwrap().parent.unwrap(),
            );
            let (_, bound) = context.file(file).unwrap();
            let property = bound.symbol(expression).unwrap();
            assert_eq!(
                context
                    .store()
                    .symbol(owner)
                    .and_then(ts_binder::semantic::Symbol::exports)
                    .and_then(|exports| context.store().symbol_table(exports))
                    .and_then(|exports| exports.get_source("value")),
                Some(property),
            );
            assert_eq!(
                context.store().symbol(property).unwrap().flags(),
                SymbolFlags::PROPERTY | SymbolFlags::ASSIGNMENT,
            );
            let number = context.store().intrinsic_bootstrap().unwrap().number_type;
            assert_eq!(
                context
                    .store()
                    .value_symbol_links(property)
                    .and_then(|links| links.resolved_type),
                Some(number),
            );
            assert_eq!(resolved_node_type(&context, left), number);
            assert_eq!(
                resolved_node_type(&context, expression),
                resolved_node_type(&context, right),
            );
            assert_eq!(
                variable_value_type(&context, &source, file, "copied"),
                number,
            );
            let copied = variable_initializer(&source, file, "copied");
            assert_eq!(
                context
                    .store()
                    .symbol_node_links(copied)
                    .and_then(|links| links.resolved_symbol),
                Some(property),
            );
            assert!(context.diagnostics().is_empty());

            let warm = observable_state(&context, file);
            context.recheck_source_file(file).unwrap();
            assert_eq!(observable_state(&context, file), warm);
        }
    }

    #[test]
    fn typescript_function_expression_expandos_publish_properties_before_later_reads() {
        let source = parsed(concat!(
            "const f = function () {}; ",
            "f.a = 1; ",
            "const x = f.a; ",
            "export {};",
        ));
        let file = FileId::new(8_489);
        let mut context = context_with_module_state(
            &[(file, &source)],
            CanonicalModuleState::External,
            CanonicalCheckerOptions::default(),
        );

        context.check_source_file(file).unwrap();

        let function = variable_initializer(&source, file, "f");
        let (left, right) = assignment_parts(&source, file, 0);
        let assignment = NodeRef::new(
            source.arena.id(),
            file,
            source.arena.get(left.node).unwrap().parent.unwrap(),
        );
        let (_, bound) = context.file(file).unwrap();
        let owner = bound.symbol(function).unwrap();
        let property = bound.symbol(assignment).unwrap();
        assert_eq!(
            context
                .store()
                .symbol(owner)
                .and_then(ts_binder::semantic::Symbol::exports)
                .and_then(|exports| context.store().symbol_table(exports))
                .and_then(|exports| exports.get_source("a")),
            Some(property),
        );
        let number = context.store().intrinsic_bootstrap().unwrap().number_type;
        assert_eq!(
            context
                .store()
                .value_symbol_links(property)
                .and_then(|links| links.resolved_type),
            Some(number),
        );
        assert_eq!(resolved_node_type(&context, left), number);
        assert_eq!(
            resolved_node_type(&context, assignment),
            resolved_node_type(&context, right),
        );
        let read = variable_initializer(&source, file, "x");
        assert_eq!(variable_value_type(&context, &source, file, "x"), number);
        assert_eq!(
            context
                .store()
                .symbol_node_links(read)
                .and_then(|links| links.resolved_symbol),
            Some(property),
        );
        assert!(context.diagnostics().is_empty());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn javascript_function_expando_jsdoc_annotations_type_properties_and_reads() {
        for (index, (source_text, object_property, incompatible)) in [
            (
                concat!(
                    "function work() {}\n",
                    "/** @type {string} */\n",
                    "work.value = 'ready';\n",
                    "const copied = work.value;",
                ),
                false,
                false,
            ),
            (
                concat!(
                    "function work() {}\n",
                    "/** @type {string} */\n",
                    "work.value = 1;\n",
                    "const copied = work.value;",
                ),
                false,
                true,
            ),
            (
                concat!(
                    "function work() {}\n",
                    "/** @type {{ ready: boolean }} */\n",
                    "work.value = { ready: true };\n",
                    "const copied = work.value.ready;",
                ),
                true,
                false,
            ),
        ]
        .into_iter()
        .enumerate()
        {
            let source = parse_javascript_source_file(source_text);
            assert!(source.diagnostics.is_empty(), "{:?}", source.diagnostics);
            let file = FileId::new(8_465 + u32::try_from(index).unwrap());
            let mut context = javascript_context(file, &source, CanonicalCheckerOptions::default());

            context.check_source_file(file).unwrap();

            let owner = function_symbol(&context, &source, file, "work");
            let property = context
                .store()
                .symbol(owner)
                .and_then(ts_binder::semantic::Symbol::exports)
                .and_then(|exports| context.store().symbol_table(exports))
                .and_then(|exports| exports.get_source("value"))
                .unwrap();
            let property_type = context
                .store()
                .value_symbol_links(property)
                .and_then(|links| links.resolved_type)
                .unwrap();
            let expected = if object_property {
                context.store().intrinsic_bootstrap().unwrap().boolean_type
            } else {
                context.store().intrinsic_bootstrap().unwrap().string_type
            };
            if !object_property {
                assert_eq!(property_type, expected);
            }
            assert_eq!(
                variable_value_type(&context, &source, file, "copied"),
                expected,
            );

            if incompatible {
                let [diagnostic] = context.diagnostics().as_slice() else {
                    panic!("expected one annotated function-property assignment diagnostic")
                };
                assert_eq!(diagnostic.diagnostic.code(), 2322);
                assert_eq!(diagnostic.diagnostic.arguments, ["number", "string"]);
                assert_eq!(node_text(&source, diagnostic.node.unwrap()), "work.value");
            } else {
                assert!(context.diagnostics().is_empty());
            }

            let warm = observable_state(&context, file);
            context.recheck_source_file(file).unwrap();
            assert_eq!(observable_state(&context, file), warm);
        }
    }

