    #[test]
    fn computed_binding_bigint_literals_use_the_primitive_index_diagnostic_name() {
        let source = parsed(concat!(
            "const { [1n]: direct } = {}; ",
            "const key = 1n; const { [key]: indirect } = {};",
        ));
        let file = FileId::new(10_417);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let [direct_name, direct_index, indirect_name, indirect_index] =
            context.diagnostics().as_slice()
        else {
            panic!("expected a computed-name and index diagnostic for each bigint key")
        };
        assert_eq!(direct_name.diagnostic.code(), 2464);
        assert_eq!(node_text(&source, direct_name.node.unwrap()), "[1n]");
        assert_eq!(direct_index.diagnostic.code(), 2538);
        assert_eq!(node_text(&source, direct_index.node.unwrap()), "1n");
        assert_eq!(direct_index.diagnostic.arguments, ["bigint"]);
        assert_eq!(indirect_name.diagnostic.code(), 2464);
        assert_eq!(node_text(&source, indirect_name.node.unwrap()), "[key]");
        assert_eq!(indirect_index.diagnostic.code(), 2538);
        assert_eq!(indirect_index.diagnostic.arguments, ["1n"]);
        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn computed_binding_any_indices_use_signatures_and_keep_any_recovery() {
        let source = parsed(concat!(
            "declare const key: any; ",
            "declare const strings: { [name: string]: number }; ",
            "declare const numbers: { [index: number]: string }; ",
            "const { [key]: stringFirst, [key]: stringSecond } = strings; ",
            "const { [key]: numberFirst, [key]: numberSecond } = numbers; ",
            "const { [key]: missing } = {};",
        ));
        let file = FileId::new(10_407);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let [diagnostic] = context.diagnostics().as_slice() else {
            panic!("only the object without an index signature should report TS2538")
        };
        assert_eq!(diagnostic.diagnostic.code(), 2538);
        assert_eq!(diagnostic.diagnostic.arguments, ["any"]);
        let bootstrap = context.store().intrinsic_bootstrap().unwrap();
        for (name, expected) in [
            ("stringFirst", bootstrap.number_type),
            ("stringSecond", bootstrap.number_type),
            ("numberFirst", bootstrap.string_type),
            ("numberSecond", bootstrap.string_type),
            ("missing", bootstrap.any_type),
        ] {
            assert_eq!(
                object_binding_value_type(&context, &source, file, name),
                expected,
                "{name}",
            );
        }
        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn computed_binding_index_results_reject_changed_source_annotations() {
        for (index, (key_annotation, annotation, change_key, change_annotation_cache)) in [
            ("any", "number", false, false),
            ("any", "number", true, false),
            ("any", "Value", false, true),
            ("never", "number", false, false),
            ("never", "number", true, false),
            ("never", "Value", false, true),
        ]
        .into_iter()
        .enumerate()
        {
            let source = parsed(&format!(
                "type Value = number; declare const key: {key_annotation}; \
                 declare const input: {{ [name: string]: {annotation} }}; \
                 const {{ [key]: first, [key]: second }} = input;",
            ));
            let file = FileId::new(10_418 + u32::try_from(index).unwrap());
            let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());
            context.check_source_file(file).unwrap();
            let receiver = variable_value_type(&context, &source, file, "input");
            let index_type = variable_value_type(&context, &source, file, "key");
            let binding = source
                .arena
                .iter()
                .find_map(|(node, record)| {
                    (record.kind == SyntaxKind::BindingElement).then_some(NodeRef::new(
                        source.arena.id(),
                        file,
                        node,
                    ))
                })
                .unwrap();
            let (members, properties, declaration) = {
                let structured = context
                    .store()
                    .type_payload(receiver)
                    .unwrap()
                    .data()
                    .structured()
                    .unwrap();
                let [index] = structured.index_infos.as_deref().unwrap() else {
                    panic!("expected the declared string index")
                };
                (
                    structured.members,
                    structured.properties.clone(),
                    context.store().index_info(*index).unwrap().declaration(),
                )
            };
            let (string, number) = {
                let bootstrap = context.store().intrinsic_bootstrap().unwrap();
                (bootstrap.string_type, bootstrap.number_type)
            };
            let replacement = context
                .store_mut_for_test()
                .alloc_index_info(
                    if change_key { number } else { string },
                    if change_key { number } else { string },
                    false,
                    declaration,
                    Vec::new(),
                )
                .unwrap();
            assert!(context.store_mut_for_test().set_structured_type_members(
                receiver,
                members,
                properties,
                None,
                None,
                Some(vec![replacement]),
            ));
            if change_annotation_cache {
                let declaration = declaration.unwrap();
                let NodeData::IndexSignatureDeclaration(signature) =
                    &source.arena.get(declaration.node).unwrap().data
                else {
                    unreachable!()
                };
                let value = NodeRef::new(source.arena.id(), file, signature.type_);
                assert!(context.store_mut_for_test().set_type_node_links(
                    value,
                    TypeNodeLinks {
                        resolved_type: Some(string),
                        ..TypeNodeLinks::default()
                    },
                ));
            }
            let bound = context.file(file).unwrap().1.clone();
            let host = DeclaredTypeHost::new([(&source.arena, &bound)]).unwrap();
            let globals = context.global_types().clone();
            let before = observable_state(&context, file);

            assert!(
                check_computed_binding_element(
                    context.store_mut_for_test(),
                    &host,
                    &globals,
                    CanonicalCheckerOptions::default(),
                    binding,
                    receiver,
                    index_type,
                )
                .is_err()
            );
            assert_eq!(observable_state(&context, file), before);
        }
    }

    #[test]
    fn computed_binding_invalid_keys_check_names_before_index_access() {
        for (index, annotation) in ["boolean", "bigint", "unknown", "null", "undefined", "{}"]
            .into_iter()
            .enumerate()
        {
            let source = parsed(&format!(
                "declare const key: {annotation}; \
                 const {{ [key]: selected }} = {{}}; \
                 const {{ [key]: fallback = 1 }} = {{}}; \
                 const {{ [key]: dynamic }}: any = {{}};",
            ));
            let file = FileId::new(10_408 + u32::try_from(index).unwrap());
            let mut context = context(
                &[(file, &source)],
                CanonicalCheckerOptions {
                    intrinsic: IntrinsicBootstrapOptions {
                        strict_null_checks: true,
                        ..IntrinsicBootstrapOptions::default()
                    },
                    ..CanonicalCheckerOptions::default()
                },
            );

            context.check_source_file(file).unwrap();

            let [name, index, default_name, any_name] = context.diagnostics().as_slice() else {
                panic!("expected three invalid names and one invalid index for {annotation}")
            };
            for diagnostic in [name, default_name, any_name] {
                assert_eq!(diagnostic.diagnostic.code(), 2464);
                assert_eq!(node_text(&source, diagnostic.node.unwrap()), "[key]");
            }
            assert_eq!(index.diagnostic.code(), 2538);
            assert_eq!(node_text(&source, index.node.unwrap()), "key");
            assert_eq!(index.diagnostic.arguments, [annotation]);
            let bootstrap = context.store().intrinsic_bootstrap().unwrap();
            assert_eq!(
                object_binding_value_type(&context, &source, file, "selected"),
                bootstrap.error_type,
            );
            assert_eq!(
                object_binding_value_type(&context, &source, file, "dynamic"),
                bootstrap.any_type,
            );
            assert_eq!(
                context
                    .type_to_string(object_binding_value_type(
                        &context, &source, file, "fallback"
                    ))
                    .unwrap(),
                "1",
            );
            let warm = observable_state(&context, file);
            context.recheck_source_file(file).unwrap();
            assert_eq!(observable_state(&context, file), warm);
        }
    }

    #[test]
    fn computed_object_binding_defaults_reject_poisoned_symbol_links() {
        let source = parsed(concat!(
            "interface Input { optional?: string; } ",
            "declare const input: Input; ",
            "const { ['optional']: selected = 'fallback' } = input;",
        ));
        let file = FileId::new(10_318);
        let mut context = context(
            &[(file, &source)],
            CanonicalCheckerOptions {
                intrinsic: IntrinsicBootstrapOptions {
                    strict_null_checks: true,
                    ..IntrinsicBootstrapOptions::default()
                },
                ..CanonicalCheckerOptions::default()
            },
        );

        context.check_source_file(file).unwrap();

        let binding = source
            .arena
            .iter()
            .find_map(|(node, record)| {
                let NodeData::BindingElement(element) = &record.data else {
                    return None;
                };
                let name = element.name.and_then(|name| source.arena.get(name))?;
                matches!(&name.data, NodeData::Identifier(identifier)
                    if identifier.text == "selected")
                .then_some(NodeRef::new(source.arena.id(), file, node))
            })
            .unwrap();
        let symbol = context.file(file).unwrap().1.symbol(binding).unwrap();
        let expected = context.store().value_symbol_links(symbol).cloned().unwrap();
        let mut poisoned = expected.clone();
        poisoned.write_type = Some(context.store().intrinsic_bootstrap().unwrap().number_type);
        mark_source_unchecked(&mut context, file);
        assert!(
            context
                .store_mut_for_test()
                .set_value_symbol_links(symbol, poisoned)
        );
        let before = observable_state(&context, file);

        assert!(matches!(
            context.check_source_file(file),
            Err(SourceCheckError::Variable(VariableInvariant::InvalidValueLinks(actual)))
                if actual == symbol
        ));
        assert_eq!(observable_state(&context, file), before);

        assert!(
            context
                .store_mut_for_test()
                .set_value_symbol_links(symbol, expected)
        );
        context.check_source_file(file).unwrap();
        assert!(is_type_checked(&context, file));
    }

