    #[test]
    fn unannotated_rest_parameters_use_ts7019_and_ordinary_parameters_keep_ts7006() {
        for (index, enabled) in [false, true].into_iter().enumerate() {
            let source = parsed("function collect(first, ...values) {}");
            let file = FileId::new(8_273 + u32::try_from(index).unwrap());
            let mut context = context(
                &[(file, &source)],
                CanonicalCheckerOptions {
                    no_implicit_any: enabled,
                    ..CanonicalCheckerOptions::default()
                },
            );

            context.check_source_file(file).unwrap();

            if enabled {
                let [ordinary, rest] = context.diagnostics().as_slice() else {
                    panic!("expected ordinary and rest implicit-any diagnostics")
                };
                assert_eq!(ordinary.diagnostic.code(), 7006);
                assert_eq!(
                    ordinary.diagnostic.render().unwrap(),
                    "Parameter 'first' implicitly has an 'any' type."
                );
                assert_eq!(node_text(&source, ordinary.node.unwrap()), "first");
                assert_eq!(rest.diagnostic.code(), 7019);
                assert_eq!(
                    rest.diagnostic.render().unwrap(),
                    "Rest parameter 'values' implicitly has an 'any[]' type."
                );
                assert_eq!(node_text(&source, rest.node.unwrap()), "...values");
            } else {
                assert!(context.diagnostics().is_empty());
            }

            let declaration = function_declaration(&source, file, "collect");
            let (_, bound) = context.file(file).unwrap();
            let owner = bound.symbol(declaration).unwrap();
            let callable = context
                .store()
                .source_callable_type_for_owner(owner)
                .unwrap();
            let signature = context
                .store()
                .source_callable_provenance(callable)
                .unwrap()
                .signature;
            assert!(
                context
                    .store()
                    .signature(signature)
                    .unwrap()
                    .has_rest_parameter()
            );
            assert_eq!(
                context
                    .store()
                    .callable_signature_parameter_types(signature)
                    .and_then(|types| types.last().copied()),
                Some(context.global_types().any_array_type)
            );

            let warm = observable_state(&context, file);
            context.recheck_source_file(file).unwrap();
            assert_eq!(observable_state(&context, file), warm);
        }
    }

    #[test]
    fn declaration_only_rest_signatures_preserve_call_overloads_without_publication() {
        for (index, calls) in [
            "(_i: number, ...restParameters);",
            concat!(
                "(_i: number, ...firstRest);",
                "(_j: number, ...secondRest);",
            ),
        ]
        .into_iter()
        .enumerate()
        {
            let text = format!(
                concat!(
                    "var v1: (_i: number, ...restParameters) => void; ",
                    "var v2: {{ {calls} ",
                    "new (_i: number, ...restParameters); ",
                    "foo(_i: number, ...restParameters); ",
                    "prop: (_i: number, ...restParameters) => void; }};",
                ),
                calls = calls,
            );
            let source = parsed(&text);
            let file = FileId::new(9_920 + u32::try_from(index).unwrap());
            let mut context = context(
                &[(file, &source)],
                CanonicalCheckerOptions {
                    no_implicit_any: false,
                    ..CanonicalCheckerOptions::default()
                },
            );
            let literal = source
                .arena
                .iter()
                .find_map(|(node, record)| {
                    (record.kind == SyntaxKind::TypeLiteral).then_some(NodeRef::new(
                        source.arena.id(),
                        file,
                        node,
                    ))
                })
                .unwrap();
            let (_, bound) = context.file(file).unwrap();
            let owner = bound.symbol(literal).unwrap();
            let members = context
                .store()
                .symbol(owner)
                .and_then(ts_binder::semantic::Symbol::members)
                .and_then(|members| context.store().symbol_table(members))
                .unwrap();
            let call = members.get(InternalSymbolName::Call.as_ref()).unwrap();
            let construct = members.get(InternalSymbolName::New.as_ref()).unwrap();
            let declarations = context
                .store()
                .symbol(call)
                .and_then(ts_binder::semantic::Symbol::declarations)
                .unwrap()
                .to_vec();
            assert_eq!(declarations.len(), index + 1);
            assert_ne!(call, construct);
            let before = (
                context.store().type_len(),
                context.store().signature_len(),
                context.store().symbol_len(),
            );

            context.check_source_file(file).unwrap();

            assert!(context.diagnostics().is_empty());
            assert_eq!(
                context
                    .store()
                    .symbol(call)
                    .and_then(ts_binder::semantic::Symbol::declarations),
                Some(declarations.as_slice()),
            );
            for declaration in declarations {
                assert!(context.store().signature_links(declaration).is_none());
            }
            assert_eq!(
                (
                    context.store().type_len(),
                    context.store().signature_len(),
                    context.store().symbol_len(),
                ),
                before,
            );

            let warm = observable_state(&context, file);
            context.recheck_source_file(file).unwrap();
            assert_eq!(observable_state(&context, file), warm);
        }
    }

