    #[test]
    fn strict_type_signature_arguments_retain_exact_binder_diagnostics() {
        let text = concat!(
            "var v1: (i: number, ...arguments) => void;\n",
            "var v12: (arguments: number, ...restParameters) => void;\n",
            "var v2: {\n",
            "    (arguments: number, ...restParameters);\n",
            "    new (arguments: number, ...restParameters);\n",
            "    foo(arguments: number, ...restParameters);\n",
            "    prop: (arguments: number, ...restParameters) => void;\n",
            "}\n",
            "var v21: {\n",
            "    (i: number, ...arguments);\n",
            "    new (i: number, ...arguments);\n",
            "    foo(i: number, ...arguments);\n",
            "    prop: (i: number, ...arguments) => void;\n",
            "}",
        );
        let source = parsed(text);
        let file = FileId::new(9_940);
        let mut binder = CanonicalBinder::new();
        binder
            .bind_source_file_with_facts(
                &source.arena,
                source.source_file,
                file,
                CanonicalSourceFileFacts::new(
                    EscapedName::source("\"/project/arguments.ts\""),
                    CanonicalSourceLanguage::TypeScript,
                    false,
                    CanonicalModuleState::Script,
                )
                .with_always_strict(true),
            )
            .unwrap();
        binder
            .bind_typescript_declaration_slice(&source.arena, file)
            .unwrap();
        let expected = binder
            .file(file)
            .unwrap()
            .diagnostics()
            .iter()
            .map(|diagnostic| {
                assert_eq!(diagnostic.diagnostic.code(), 1100);
                assert_eq!(diagnostic.diagnostic.arguments, ["arguments"]);
                source.arena.get(diagnostic.node.node).unwrap().range
            })
            .collect::<Vec<_>>();
        assert_eq!(expected.len(), 10);
        let mut context = CanonicalCheckerContext::new(
            binder.finish(),
            vec![(file, &source.arena)],
            CanonicalCheckerOptions {
                no_implicit_any: false,
                ..CanonicalCheckerOptions::default()
            },
        )
        .unwrap();

        context.check_source_file(file).unwrap();

        assert!(context.diagnostics().is_empty());
        let (_, bound) = context.file(file).unwrap();
        assert_eq!(
            bound
                .diagnostics()
                .iter()
                .map(|diagnostic| source.arena.get(diagnostic.node.node).unwrap().range)
                .collect::<Vec<_>>(),
            expected,
        );

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn generic_predicate_interface_calls_preserve_constructor_identity_cold_and_warm() {
        let source = parsed(concat!(
            "interface Bullean {} ",
            "interface BulleanConstructor { ",
            "new(v1?: any): Bullean; ",
            "<T>(v2?: T): v2 is T; ",
            "} ",
            "declare var Bullean: BulleanConstructor;",
        ));
        let file = FileId::new(9_939);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let owner = global_symbol(&context, "BulleanConstructor");
        let declared = context
            .store()
            .declared_type_links(owner)
            .and_then(|links| links.declared_type)
            .unwrap();
        let TypeData::Interface(interface) = context.store().type_payload(declared).unwrap().data()
        else {
            panic!("the predicate constructor must retain its interface identity")
        };
        let [call] = interface.declared_call_signatures.as_deref().unwrap() else {
            panic!("the predicate constructor must retain one generic call")
        };
        let [constructor] = interface.declared_construct_signatures.as_deref().unwrap() else {
            panic!("the predicate constructor must retain its original constructor")
        };
        let call = *call;
        let constructor = *constructor;
        assert_eq!(
            interface.reference.object.structured.signatures.as_deref(),
            Some([call, constructor].as_slice()),
        );
        let signature = context.store().signature(call).unwrap();
        let [type_parameter] = signature.type_parameters() else {
            panic!("the predicate call must retain its binder-owned type parameter")
        };
        let type_parameter = *type_parameter;
        assert_eq!(signature.min_argument_count(), 0);
        assert_eq!(
            signature.resolved_return_type(),
            Some(context.store().intrinsic_bootstrap().unwrap().boolean_type),
        );
        assert_eq!(
            context.store().callable_signature_parameter_types(call),
            Some([type_parameter].as_slice()),
        );
        let predicate = signature
            .resolved_type_predicate()
            .and_then(|predicate| context.store().type_predicate(predicate))
            .unwrap();
        assert_eq!(predicate.kind(), TypePredicateKind::Identifier);
        assert_eq!(predicate.parameter_index(), 0);
        assert_eq!(predicate.parameter_name(), "v2");
        assert_eq!(predicate.type_id(), Some(type_parameter));
        let bullean = global_symbol(&context, "Bullean");
        assert_eq!(
            context
                .store()
                .signature(constructor)
                .and_then(super::super::signatures::Signature::resolved_return_type),
            context
                .store()
                .declared_type_links(bullean)
                .and_then(|links| links.declared_type),
        );
        assert!(context.diagnostics().is_empty());

        let warm = (
            observable_state(&context, file),
            context.store().type_predicate_len(),
        );
        context.recheck_source_file(file).unwrap();
        assert_eq!(
            (
                observable_state(&context, file),
                context.store().type_predicate_len(),
            ),
            warm,
        );
    }

    #[test]
    fn callable_interface_members_preserve_implicit_constructor_diagnostic_gates() {
        let source = parsed(concat!(
            "interface i1 {} ",
            "interface i2 { ",
            "x: number; ",
            "foo: (b: number) => string; ",
            "[i: string]: any; ",
            "new (i: i1); ",
            "[i: number]: number; ",
            "(a: number, b: number): number; ",
            "fnfoo(b: number): string; ",
            "}",
        ));

        for (index, no_implicit_any) in [false, true].into_iter().enumerate() {
            let file = FileId::new(9_941 + u32::try_from(index).unwrap());
            let mut context = context(
                &[(file, &source)],
                CanonicalCheckerOptions {
                    no_implicit_any,
                    ..CanonicalCheckerOptions::default()
                },
            );

            context.check_source_file(file).unwrap();

            let owner = global_symbol(&context, "i2");
            let type_ = context
                .store()
                .declared_type_links(owner)
                .and_then(|links| links.declared_type)
                .unwrap();
            let TypeData::Interface(interface) =
                context.store().type_payload(type_).unwrap().data()
            else {
                panic!("the comments interface must retain its declared identity")
            };
            assert_eq!(
                interface
                    .reference
                    .object
                    .structured
                    .properties
                    .as_ref()
                    .map(Vec::len),
                Some(3),
            );
            assert_eq!(
                interface.declared_index_infos.as_ref().map(Vec::len),
                Some(2)
            );
            assert_eq!(
                interface.declared_call_signatures.as_ref().map(Vec::len),
                Some(1)
            );
            let [constructor] = interface.declared_construct_signatures.as_deref().unwrap() else {
                panic!("the comments interface must retain one constructor")
            };
            let constructor = *constructor;
            assert_eq!(
                context
                    .store()
                    .signature(constructor)
                    .and_then(super::super::signatures::Signature::resolved_return_type),
                Some(context.store().intrinsic_bootstrap().unwrap().any_type),
            );
            assert!(matches!(
                super::super::object_members::validate_stored_declared_call_set(
                    context.store(),
                    type_,
                ),
                super::super::object_members::StoredDeclaredCallSetValidation::Valid(_)
            ));
            if no_implicit_any {
                let [diagnostic] = context.diagnostics().as_slice() else {
                    panic!("the implicit constructor return must report exactly one diagnostic")
                };
                assert_eq!(diagnostic.diagnostic.code(), 7013);
                assert_eq!(node_text(&source, diagnostic.node.unwrap()), "new (i: i1);");
                assert_eq!(
                    diagnostic.diagnostic.render().unwrap(),
                    "Construct signature, which lacks return-type annotation, implicitly has an 'any' return type.",
                );
            } else {
                assert!(context.diagnostics().is_empty());
            }

            let expected_diagnostics = context.diagnostics().clone();
            let warm = observable_state(&context, file);
            context.recheck_source_file(file).unwrap();
            assert_eq!(observable_state(&context, file), warm);
            assert_eq!(context.diagnostics(), &expected_diagnostics);
        }
    }

